import { useState } from "react";
import {
  Button, Modal, Form, Input, Select, Table, Tag, Space,
  Typography, Descriptions, Divider, message, Badge, Tooltip,
} from "antd";
import {
  CheckCircleOutlined, CloseCircleOutlined, EyeOutlined,
  ShopOutlined, ReloadOutlined,
} from "@ant-design/icons";
import { useTranslation } from "react-i18next";
import type { ColumnsType } from "antd/es/table";
import type { StallApplication } from "@kawkaw/shared";
import dayjs from "dayjs";
import { AdminShell } from "../layouts/AdminShell";
import { useStallApplications, useStallApplication, useReviewStallApplication } from "../api/hooks";

const { Title, Text } = Typography;
const { TextArea } = Input;

const STATUS_COLOR: Record<string, string> = {
  pending: "orange",
  approved: "green",
  rejected: "red",
};

export function StallApplicationsScreen() {
  const { t } = useTranslation();
  const [statusFilter, setStatusFilter] = useState<string | undefined>(undefined);
  const [page, setPage] = useState(1);
  const [viewApp, setViewApp] = useState<StallApplication | null>(null);
  const [reviewModal, setReviewModal] = useState<{ app: StallApplication; decision: "approve" | "reject" } | null>(null);
  const [form] = Form.useForm();

  const { data, isLoading, refetch } = useStallApplications({ status: statusFilter, page, limit: 20 });
  // Fresh detail fetch when the drawer opens — picks up reviewer name + latest status if it changed in another tab.
  const { data: detailData } = useStallApplication(viewApp?.id ?? null);
  const liveApp = detailData?.data ?? viewApp;
  const review = useReviewStallApplication();

  const handleReview = async (values: { review_note?: string; sort_order?: number }) => {
    if (!reviewModal) return;
    try {
      await review.mutateAsync({
        id: reviewModal.app.id,
        decision: reviewModal.decision,
        review_note: values.review_note,
        sort_order: values.sort_order,
      });
      void message.success(
        reviewModal.decision === "approve"
          ? t("stallApplications.approvedMsg")
          : t("stallApplications.rejectedMsg"),
      );
      setReviewModal(null);
      form.resetFields();
    } catch {
      void message.error(t("stallApplications.failedMsg"));
    }
  };

  const columns: ColumnsType<StallApplication> = [
    {
      title: t("stallApplications.colCreatedAt"),
      dataIndex: "created_at",
      key: "created_at",
      width: 160,
      render: (v: string) => dayjs(v).format("YYYY-MM-DD HH:mm"),
    },
    {
      title: t("stallApplications.colStallName"),
      dataIndex: "stall_name",
      key: "stall_name",
      render: (v: string) => <Text strong>{v}</Text>,
    },
    {
      title: t("stallApplications.colCategory"),
      dataIndex: "category",
      key: "category",
      render: (v: string | null) => v ? <Tag>{v}</Tag> : <Text type="secondary">—</Text>,
    },
    {
      title: t("stallApplications.colContact"),
      key: "contact",
      render: (_: unknown, r: StallApplication) => (
        <div>
          <div>{r.contact_name}</div>
          <Text type="secondary" style={{ fontSize: 12 }}>{r.contact_phone}</Text>
        </div>
      ),
    },
    {
      title: t("stallApplications.colStatus"),
      dataIndex: "status",
      key: "status",
      width: 100,
      render: (v: string) => (
        <Badge color={STATUS_COLOR[v] ?? "default"} text={t(`stallApplications.status.${v}`, { defaultValue: v })} />
      ),
    },
    {
      title: t("stallApplications.colReviewer"),
      key: "reviewer",
      width: 120,
      render: (_: unknown, r: StallApplication) =>
        r.reviewer ? <Text>{r.reviewer.name}</Text> : <Text type="secondary">—</Text>,
    },
    {
      title: t("stallApplications.colActions"),
      key: "actions",
      width: 160,
      render: (_: unknown, r: StallApplication) => (
        <Space>
          <Tooltip title={t("stallApplications.viewDetail")}>
            <Button size="small" icon={<EyeOutlined />} onClick={() => setViewApp(r)} />
          </Tooltip>
          {r.status === "pending" && (
            <>
              <Tooltip title={t("stallApplications.approve")}>
                <Button
                  size="small"
                  type="primary"
                  icon={<CheckCircleOutlined />}
                  onClick={() => { form.resetFields(); setReviewModal({ app: r, decision: "approve" }); }}
                />
              </Tooltip>
              <Tooltip title={t("stallApplications.reject")}>
                <Button
                  size="small"
                  danger
                  icon={<CloseCircleOutlined />}
                  onClick={() => { form.resetFields(); setReviewModal({ app: r, decision: "reject" }); }}
                />
              </Tooltip>
            </>
          )}
        </Space>
      ),
    },
  ];

  return (
    <AdminShell>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
        <Title level={4} style={{ margin: 0 }}>
          <ShopOutlined style={{ marginRight: 8 }} />
          {t("stallApplications.title")}
        </Title>
        <Space>
          <Select
            style={{ width: 140 }}
            placeholder={t("stallApplications.filterStatus")}
            allowClear
            value={statusFilter}
            onChange={(v) => { setStatusFilter(v); setPage(1); }}
            options={[
              { value: "pending", label: t("stallApplications.status.pending") },
              { value: "approved", label: t("stallApplications.status.approved") },
              { value: "rejected", label: t("stallApplications.status.rejected") },
            ]}
          />
          <Button icon={<ReloadOutlined />} onClick={() => void refetch()}>{t("common.refresh")}</Button>
        </Space>
      </div>

      <Table<StallApplication>
        rowKey="id"
        columns={columns}
        dataSource={data?.data ?? []}
        loading={isLoading}
        pagination={{
          current: page,
          pageSize: 20,
          total: data?.meta.total ?? 0,
          onChange: (p) => setPage(p),
          showTotal: (total) => t("common.total", { count: total }),
        }}
      />

      {/* Detail view modal */}
      <Modal
        open={!!viewApp}
        title={t("stallApplications.detailTitle")}
        footer={null}
        onCancel={() => setViewApp(null)}
        width={600}
      >
        {liveApp && (
          <>
            <Descriptions bordered column={1} size="small">
              <Descriptions.Item label={t("stallApplications.colStallName")}>{liveApp.stall_name}</Descriptions.Item>
              <Descriptions.Item label={t("stallApplications.colCategory")}>{liveApp.category ?? "—"}</Descriptions.Item>
              <Descriptions.Item label={t("stallApplications.labelDescription")}>{liveApp.description ?? "—"}</Descriptions.Item>
              <Descriptions.Item label={t("stallApplications.colContact")}>{liveApp.contact_name}</Descriptions.Item>
              <Descriptions.Item label={t("stallApplications.labelContactPhone")}>{liveApp.contact_phone}</Descriptions.Item>
              <Descriptions.Item label={t("stallApplications.labelContactEmail")}>{liveApp.contact_email ?? "—"}</Descriptions.Item>
              <Descriptions.Item label={t("stallApplications.colStatus")}>
                <Tag color={STATUS_COLOR[liveApp.status]}>{t(`stallApplications.status.${liveApp.status}`, { defaultValue: liveApp.status })}</Tag>
              </Descriptions.Item>
              {liveApp.review_note && (
                <Descriptions.Item label={t("stallApplications.labelReviewNote")}>{liveApp.review_note}</Descriptions.Item>
              )}
              {liveApp.reviewer && (
                <Descriptions.Item label={t("stallApplications.colReviewer")}>{liveApp.reviewer.name}</Descriptions.Item>
              )}
              <Descriptions.Item label={t("stallApplications.labelAppliedAt")}>{dayjs(liveApp.created_at).format("YYYY-MM-DD HH:mm:ss")}</Descriptions.Item>
            </Descriptions>
            {liveApp.status === "pending" && (
              <>
                <Divider />
                <Space>
                  <Button
                    type="primary"
                    icon={<CheckCircleOutlined />}
                    onClick={() => { setViewApp(null); form.resetFields(); setReviewModal({ app: liveApp, decision: "approve" }); }}
                  >
                    {t("stallApplications.approve")}
                  </Button>
                  <Button
                    danger
                    icon={<CloseCircleOutlined />}
                    onClick={() => { setViewApp(null); form.resetFields(); setReviewModal({ app: liveApp, decision: "reject" }); }}
                  >
                    {t("stallApplications.reject")}
                  </Button>
                </Space>
              </>
            )}
          </>
        )}
      </Modal>

      {/* Review decision modal */}
      <Modal
        open={!!reviewModal}
        title={reviewModal?.decision === "approve" ? t("stallApplications.approveModalTitle") : t("stallApplications.rejectModalTitle")}
        onCancel={() => setReviewModal(null)}
        onOk={() => form.submit()}
        okText={reviewModal?.decision === "approve" ? t("stallApplications.confirmApprove") : t("stallApplications.confirmReject")}
        okButtonProps={{
          danger: reviewModal?.decision === "reject",
          loading: review.isPending,
        }}
      >
        {reviewModal && (
          <>
            <Text>
              {reviewModal.decision === "approve"
                ? t("stallApplications.approveDescription", { name: reviewModal.app.stall_name })
                : t("stallApplications.rejectDescription", { name: reviewModal.app.stall_name })}
            </Text>
            <Divider style={{ margin: "12px 0" }} />
            <Form form={form} layout="vertical" onFinish={handleReview}>
              {reviewModal.decision === "approve" && (
                <Form.Item name="sort_order" label={t("stallApplications.sortOrderLabel")}>
                  <Input type="number" min={0} placeholder="99" style={{ width: 120 }} />
                </Form.Item>
              )}
              <Form.Item
                name="review_note"
                label={reviewModal.decision === "reject" ? t("stallApplications.rejectionReason") : t("stallApplications.reviewNoteOptional")}
                rules={
                  reviewModal.decision === "reject"
                    ? [{ min: 5, message: t("stallApplications.rejectionReason") }]
                    : []
                }
              >
                <TextArea
                  rows={3}
                  placeholder={reviewModal.decision === "reject"
                    ? t("stallApplications.rejectionPlaceholder")
                    : t("stallApplications.reviewNotePlaceholder")}
                />
              </Form.Item>
            </Form>
          </>
        )}
      </Modal>
    </AdminShell>
  );
}
