const { Text } = Typography;

const TXN_STATUS_STYLE: Record<string, { bg: string; color: string; labelKey: string }> = {
  success:        { bg: T.successDeep, color: T.surface,     labelKey: "transactionDetail.statusPaid" },
  partial_refund: { bg: T.brand, color: T.surface,     labelKey: "transactionDetail.statusPartialRefund" },
  refunded:       { bg: T.dangerBg, color: T.dangerText,  labelKey: "transactionDetail.statusRefunded" },
  pending:        { bg: "#FEF9C3", color: T.warningDeep,  labelKey: "transactionDetail.statusPending" },
  failed:         { bg: T.surfaceSection, color: T.textSecondary,  labelKey: "transactionDetail.statusFailed" },
};

function txnStatusStyle(status: string, t: TFunction) {
  const row = TXN_STATUS_STYLE[status];
  if (row) return { bg: row.bg, color: row.color, label: t(row.labelKey) };
  return { bg: T.surfaceSection, color: T.textSecondary, label: status.replace(/_/g, " ").toUpperCase() };
}

function paymentMethodLabel(t: TFunction, method: string): string {
  const key = `orderDetail.payment.${method}`;
  const tr = t(key);
  return tr === key ? method : tr;
}

const REFUND_STATUS_MAP: Record<string, { bg: string; color: string }> = {
  completed: { bg: T.surfaceGreen, color: T.successText },
  approved:  { bg: T.surfaceGreen, color: T.successText },
  pending:   { bg: "#FEF9C3", color: T.warningDeep },
  rejected:  { bg: T.dangerBg, color: T.dangerText },
};

function txnDisplayCode(id: string, ref: string | null) {
  if (ref) return ref.toUpperCase();
  return `TXN-${id.slice(0, 12).toUpperCase()}`;
}

function buildTimeline(txn: NonNullable<ReturnType<typeof useAdminTransaction>["data"]>, t: TFunction) {
  type TimelineEvent = { id: string; ts: string; title: string; desc: string; dot: "green" | "orange" | "red" | "grey" };
  const events: TimelineEvent[] = [];

  const ACTION_LABELS: Record<string, string> = {
    "refund.create":  "transactionDetail.timelineRefundInitiated",
    "refund.approve": "transactionDetail.timelineRefundApproved",
    "refund.reject":  "transactionDetail.timelineRefundRejected",
    "order.admin_cancel": "transactionDetail.timelineOrderCancelled",
  };
  for (const log of txn.activity_logs ?? []) {
    const labelKey = ACTION_LABELS[log.action];
    const title = labelKey ? t(labelKey) : log.action.replace(/\./g, " ").replace(/\b\w/g, c => c.toUpperCase());
    const metaDesc = log.meta
      ? Object.entries(log.meta)
          .filter(([k]) => !["orderId", "prevStatus"].includes(k))
          .map(([k, v]) => `${k}: ${String(v)}`)
          .join(", ")
      : "";
    events.push({ id: log.id, ts: log.created_at, title, desc: metaDesc, dot: "grey" });
  }

  if (txn.paid_at) {
    events.push({
      id: "paid",
      ts: txn.paid_at,
      title: t("transactionDetail.timelinePaid"),
      desc: txn.reference ? t("transactionDetail.authCode", { reference: txn.reference }) : "",
      dot: "green",
    });
  }

  events.push({
    id: "initiated",
    ts: txn.created_at,
    title: t("transactionDetail.timelineInitiated"),
    desc: txn.order?.customer?.name ? t("transactionDetail.checkoutBy", { name: txn.order.customer.name }) : "",
    dot: "grey",
  });

  events.sort((a, b) => dayjs(b.ts).valueOf() - dayjs(a.ts).valueOf());
  return events;
}

