import dayjs from "dayjs";
import utc from "dayjs/plugin/utc";
import timezone from "dayjs/plugin/timezone";
import type { ConfigType } from "dayjs";

dayjs.extend(utc);
dayjs.extend(timezone);

const MYT = "Asia/Kuala_Lumpur";

export function isZhLocale(lng: string): boolean {
  return lng === "zh" || lng.startsWith("zh");
}

function d(input: ConfigType) {
  return dayjs(input).tz(MYT);
}

/** Full date + time for headers and detail rows. */
export function formatDateTimeDetail(input: ConfigType, lng: string): string {
  const x = d(input);
  if (isZhLocale(lng)) return x.format("YYYY年M月D日 HH:mm");
  return x.format("MMM D, YYYY h:mm A");
}

/** Shorter datetime for timeline sidebars. */
export function formatDateTimeCompact(input: ConfigType, lng: string): string {
  const x = d(input);
  if (isZhLocale(lng)) return x.format("M月D日 HH:mm");
  return x.format("MMM D, HH:mm");
}

/** Date only (no time). */
export function formatDateOnly(input: ConfigType, lng: string): string {
  const x = d(input);
  if (isZhLocale(lng)) return x.format("YYYY年M月D日");
  return x.format("MMM D, YYYY");
}
