const GROUP_ICON_LABEL_KEYS: Record<string, string> = {
  sugar: "menu.groupIconSugar",
  ice: "menu.groupIconIce",
  special: "menu.groupIconSpecial",
};

function GroupIcon({ iconKey, size = 16, color = "currentColor" }: { iconKey: string; size?: number; color?: string }) {
  const icon = GROUP_ICON_DEFS.find(i => i.key === iconKey);
  if (!icon) return null;
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox={icon.viewBox} fill="none" style={{ display: "block" }}>
      {icon.paths.map((d, i) => <path key={i} d={d} fill={color} />)}
    </svg>
  );
}

/* ─────────────────────────────────────────────────────────
   Option Groups Drawer
   ───────────────────────────────────────────────────────── */
function OptionGroupsDrawer({
  open, item, onClose,
}: {
  open: boolean;
  item: MenuItem | null;
  onClose: () => void;
}) {
  const { t } = useTranslation();
  const [groupForm] = Form.useForm();
  const [choiceForm] = Form.useForm();
  const activeIconKey = Form.useWatch("icon_key", { form: groupForm, preserve: true });
  const choiceInputType = Form.useWatch("input_type", { form: choiceForm, preserve: true });
  const [editingGroup, setEditingGroup] = useState<MenuOptionGroup | null>(null);
  const [editingChoice, setEditingChoice] = useState<MenuOptionChoice | null>(null);
  const [addingGroupOpen, setAddingGroupOpen] = useState(false);
  const [addingChoiceForGroup, setAddingChoiceForGroup] = useState<string | null>(null);

  const createGroup = useCreateOptionGroup();
  const updateGroup = useUpdateOptionGroup();
  const deleteGroup = useDeleteOptionGroup();
  const createChoice = useCreateOptionChoice();
  const updateChoice = useUpdateOptionChoice();
  const deleteChoice = useDeleteOptionChoice();

  const groupIcons = useMemo(
    () =>
      GROUP_ICON_DEFS.map(def => ({
        ...def,
        label: t(GROUP_ICON_LABEL_KEYS[def.key] ?? "menu.formGroupIcon"),
      })),
    [t],
  );

  const choiceInputTypeOptions = useMemo(
    () => [
      { value: "radio", label: t("menu.choiceTypeRadio") },
      { value: "input", label: t("menu.choiceTypeInputBox") },
      { value: "textarea", label: t("menu.choiceTypeTextarea") },
    ],
    [t],
  );

  const groups: MenuOptionGroup[] = (item as (MenuItem & { option_groups?: MenuOptionGroup[] }))?.option_groups ?? [];

  // ── Group handlers ──
  const openAddGroup = () => { setEditingGroup(null); groupForm.resetFields(); setAddingGroupOpen(true); };
  const openEditGroup = (g: MenuOptionGroup) => {
    setEditingGroup(g);
    groupForm.setFieldsValue({ name: g.name, type: g.type, min_select: g.min_select, max_select: g.max_select, sort_order: g.sort_order, icon_key: g.icon_key ?? null });
    setAddingGroupOpen(true);
  };
  const saveGroup = async () => {
    try {
      const vals = await groupForm.validateFields();
      if (editingGroup) {
        await updateGroup.mutateAsync({ id: editingGroup.id, ...vals });
      } else {
        await createGroup.mutateAsync({ itemId: item!.id, ...vals });
      }
      void message.success(t("menu.groupSaved"));
      setAddingGroupOpen(false);
    } catch { void message.error(t("menu.saveFailed")); }
  };
  const removeGroup = async (id: string) => {
    try {
      await deleteGroup.mutateAsync(id);
      void message.success(t("menu.groupDeleted"));
    } catch { void message.error(t("menu.deleteFailed")); }
  };

  // ── Choice handlers ──
  const openAddChoice = (groupId: string) => {
    setEditingChoice(null); choiceForm.resetFields(); setAddingChoiceForGroup(groupId);
  };
  const openEditChoice = (c: MenuOptionChoice) => {
    setEditingChoice(c);
    choiceForm.setFieldsValue({ label: c.label, extra_charge: parseFloat(c.extra_charge ?? "0"), sort_order: c.sort_order, input_type: c.input_type ?? "radio" });
    setAddingChoiceForGroup(c.group_id);
  };
  const saveChoice = async () => {
    try {
      const vals = await choiceForm.validateFields();
      if (editingChoice) {
        await updateChoice.mutateAsync({ id: editingChoice.id, ...vals });
      } else {
        await createChoice.mutateAsync({ groupId: addingChoiceForGroup!, ...vals });
      }
      void message.success(t("menu.choiceSaved"));
      setAddingChoiceForGroup(null);
    } catch { void message.error(t("menu.saveFailed")); }
  };
  const removeChoice = async (id: string) => {
    try {
      await deleteChoice.mutateAsync(id);
      void message.success(t("menu.choiceDeleted"));
    } catch { void message.error(t("menu.deleteFailed")); }
  };

  return (
    <Drawer
      open={open}
      title={t("menu.optionsDrawerTitle", { name: item?.name ?? "" })}
      onClose={onClose}
      width={520}
      extra={
        <Button type="primary" icon={<PlusOutlined />} onClick={openAddGroup}
          style={{ background: T.brandAmber, borderColor: T.brandAmber }}>
          {t("menu.addGroup")}
        </Button>
      }
    >
      {groups.length === 0 && (
        <div style={{ textAlign: "center", color: "#9CA3AF", padding: "40px 0" }}>
          {t("common.noData")}
        </div>
      )}

      <Collapse
        accordion
        items={groups.map((g) => ({
          key: g.id,
          label: (
            <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
              <Text strong>{g.name}</Text>
              <Tag color={g.type === "required" ? "red" : "blue"}>
                {g.type === "required" ? t("menu.groupTypeRequired") : t("menu.groupTypeOptional")}
              </Tag>
              <Text type="secondary" style={{ fontSize: 12 }}>
                {g.min_select}-{g.max_select} {t("menu.groupMinSelect").toLowerCase()}
              </Text>
            </div>
          ),
          extra: (
            <Space onClick={(e) => e.stopPropagation()}>
              <Tooltip title={t("common.edit")}>
                <Button size="small" icon={<EditOutlined />} onClick={() => openEditGroup(g)} />
              </Tooltip>
              <Popconfirm title={t("menu.confirmDeleteGroup")} onConfirm={() => void removeGroup(g.id)} okType="danger">
                <Button size="small" danger icon={<DeleteOutlined />} />
              </Popconfirm>
            </Space>
          ),
          children: (
            <>
              {(g.choices ?? []).map((c) => (
                <div key={c.id} style={{
                  display: "flex", alignItems: "center", justifyContent: "space-between",
                  padding: "6px 8px", background: T.bg, borderRadius: 6, marginBottom: 4,
                }}>
                  <div>
                    <Text>{c.label}</Text>
                    {parseFloat(c.extra_charge ?? "0") > 0 && (
                      <Tag color="orange" style={{ marginLeft: 8 }}>+RM {parseFloat(c.extra_charge).toFixed(2)}</Tag>
                    )}
                  </div>
                  <Space>
                    <Button size="small" icon={<EditOutlined />} onClick={() => openEditChoice(c)} />
                    <Popconfirm title={t("menu.confirmDeleteChoice")} onConfirm={() => void removeChoice(c.id)} okType="danger">
                      <Button size="small" danger icon={<DeleteOutlined />} />
                    </Popconfirm>
                  </Space>
                </div>
              ))}
              <Button size="small" icon={<PlusOutlined />} onClick={() => openAddChoice(g.id)}
                style={{ marginTop: 6, borderStyle: "dashed" }}>
                {t("menu.addChoice")}
              </Button>
            </>
          ),
        }))}
      />

      {/* Add/Edit Group Modal */}
      <Modal
        open={addingGroupOpen}
        title={editingGroup ? t("menu.editGroup") : t("menu.addGroup")}
        onCancel={() => setAddingGroupOpen(false)}
        onOk={() => void saveGroup()}
        okText={t("common.save")}
        okButtonProps={{ loading: createGroup.isPending || updateGroup.isPending, style: { background: T.brandAmber, borderColor: T.brandAmber } }}
        destroyOnHidden
      >
        <Form form={groupForm} layout="vertical">
          <Form.Item name="icon_key" label={t("menu.formGroupIcon")}>
            <div style={{ display: "flex", gap: 8 }}>
              {groupIcons.map(icon => {
                const active = activeIconKey === icon.key;
                return (
                  <button
                    key={icon.key}
                    type="button"
                    title={icon.label}
                    onClick={() => { groupForm.setFieldValue("icon_key", active ? null : icon.key); }}
                    style={{
                      width: 36, height: 36, borderRadius: 10, cursor: "pointer",
                      border: active ? "2px solid #D97706" : "1.5px solid #E5E7EB",
                      background: active ? T.brandLight : T.bg,
                      display: "flex", alignItems: "center", justifyContent: "center",
                      padding: 0, lineHeight: 1,
                    }}
                  >
                    <GroupIcon iconKey={icon.key} size={18} color={active ? T.brandAmber : T.textMuted} />
                  </button>
                );
              })}
            </div>
          </Form.Item>
          <Form.Item name="name" label={t("menu.groupName")} rules={[{ required: true }]}>
            <Input />
          </Form.Item>
          <Form.Item name="type" label={t("menu.groupType")} rules={[{ required: true }]} initialValue="optional">
            <Select options={[
              { value: "required", label: t("menu.groupTypeRequired") },
              { value: "optional", label: t("menu.groupTypeOptional") },
            ]} />
          </Form.Item>
          <Form.Item name="min_select" label={t("menu.groupMinSelect")} initialValue={0}>
            <InputNumber min={0} style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item name="max_select" label={t("menu.groupMaxSelect")} initialValue={1}>
            <InputNumber min={1} style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item name="sort_order" label={t("menu.formSortOrder")} initialValue={0}>
            <InputNumber min={0} style={{ width: "100%" }} />
          </Form.Item>
        </Form>
      </Modal>

      {/* Add/Edit Choice Modal */}
      <Modal
        open={addingChoiceForGroup !== null}
        title={editingChoice ? t("menu.editChoice") : t("menu.addChoice")}
        onCancel={() => setAddingChoiceForGroup(null)}
        onOk={() => void saveChoice()}
        okText={t("common.save")}
        okButtonProps={{ loading: createChoice.isPending || updateChoice.isPending, style: { background: T.brandAmber, borderColor: T.brandAmber } }}
        destroyOnHidden
      >
        <Form form={choiceForm} layout="vertical">
          <Form.Item name="input_type" label={t("menu.choiceInputType")} initialValue="radio">
            <Select options={choiceInputTypeOptions} />
          </Form.Item>
          {choiceInputType === "textarea" ? (
            <Form.Item name="label" label={t("menu.choicePlaceholderLabel")} rules={[{ required: true }]}>
              <Input.TextArea rows={2} placeholder={t("menu.choicePlaceholderExample")} />
            </Form.Item>
          ) : (
            <Form.Item name="label" label={t("menu.choiceLabel")} rules={[{ required: true }]}>
              <Input />
            </Form.Item>
          )}
          <Form.Item name="extra_charge" label={t("menu.choiceExtraCharge")} initialValue={0}>
            <InputNumber prefix="RM" min={0} precision={2} style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item name="sort_order" label={t("menu.formSortOrder")} initialValue={0}>
            <InputNumber min={0} style={{ width: "100%" }} />
          </Form.Item>
        </Form>
      </Modal>
    </Drawer>
  );
}

/* ─────────────────────────────────────────────────────────
   Main MenuScreen
   ───────────────────────────────────────────────────────── */
export function MenuScreen() {
  const { t } = useTranslation();
  const { message: msg } = App.useApp();
  const [stallId, setStallId] = useState<string | undefined>();
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<MenuItem | null>(null);
  const [optionsItemId, setOptionsItemId] = useState<string | null>(null);
  const [catDrawerOpen, setCatDrawerOpen] = useState(false);
  const [form] = Form.useForm();

  // Stall details panel form state
  const [stallForm] = Form.useForm();
  const [stallDirty, setStallDirty] = useState(false);
  const updateStall = useUpdateStall();

  const { data: stallsData } = useAdminStalls();
  const { data: menuData, isLoading } = useAdminMenuItems(stallId);
  const { data: catData } = useAdminMenuCategories(stallId);
  const { data: allCatData } = useAdminMenuCategories();

  const stalls: Stall[] = stallsData?.data ?? [];
  const categories: MenuCategoryRow[] = catData?.data ?? [];
  const allCategories: MenuCategoryRow[] = allCatData?.data ?? [];
  const items: MenuItem[] = menuData?.data ?? [];

  const selectedStall = stalls.find(s => s.id === stallId) ?? null;

  // Sync stall details form when selected stall changes
  useEffect(() => {
    if (selectedStall) {
      stallForm.setFieldsValue({
        name: selectedStall.name,
        description: selectedStall.description,
        is_open: selectedStall.is_open,
        prep_time: selectedStall.prep_time ?? 15,
        auto_accept: selectedStall.auto_accept ?? false,
      });
      setStallDirty(false);
    }
  }, [selectedStall, stallForm]);

  // Always derive optionsItem from live data
  const navigate = useNavigate();
  const optionsItem = optionsItemId ? items.find(it => it.id === optionsItemId) ?? null : null;
  const createItem = useCreateMenuItem();
  const updateItem = useUpdateMenuItem();
  const deleteItem = useDeleteMenuItem();

  const openCreate = () => { navigate("/menu/items/new", { state: { stallId } }); };
  const openEdit = (item: MenuItem) => {
    setEditing(item);
    const row = item as MenuItem & { categories?: Array<{ id: string }>; category_ids?: string[] };
    const categoryIds = row.categories?.map(c => c.id) ?? row.category_ids ?? [];
    form.setFieldsValue({
      ...item,
      stall_id: stallId,
      category_ids: categoryIds,
      offer_price: item.offer_price ? parseFloat(item.offer_price as unknown as string) : undefined,
    });
    setModalOpen(true);
  };

  const onSave = async (values: Partial<MenuItem>) => {
    try {
      if (editing) {
        await updateItem.mutateAsync({ id: editing.id, ...values });
        void msg.success(t("menu.updateSuccess"));
      } else {
        await createItem.mutateAsync({ ...values, stall_id: stallId });
        void msg.success(t("menu.createSuccess"));
      }
      setModalOpen(false);
    } catch {
      void msg.error(t("menu.saveFailed"));
    }
  };

  const onDelete = async (id: string) => {
    try {
      await deleteItem.mutateAsync(id);
      void msg.success(t("menu.deleteSuccess"));
    } catch {
      void msg.error(t("menu.deleteFailed"));
    }
  };

  const onToggleAvailability = async (item: MenuItem) => {
    try {
      await updateItem.mutateAsync({ id: item.id, is_available: !item.is_available });
    } catch {
      void msg.error(t("menu.saveFailed"));
    }
  };

  const onSaveStall = async () => {
    if (!stallId) return;
    try {
      const values = await stallForm.validateFields();
      await updateStall.mutateAsync({ id: stallId, ...values as { name?: string; description?: string; is_open?: boolean } });
      void msg.success(t("stalls.updateSuccess"));
      setStallDirty(false);
    } catch {
      void msg.error(t("stalls.saveFailed"));
    }
  };

  // Categories drawer state
  const [catModalOpen, setCatModalOpen] = useState(false);
  const [editingCat, setEditingCat] = useState<MenuCategoryRow | null>(null);
  const [catForm] = Form.useForm();
  const createCat = useCreateMenuCategory();
  const updateCat = useUpdateMenuCategory();
  const deleteCat = useDeleteMenuCategory();

  const saveCat = async () => {
    try {
      const vals = await catForm.validateFields();
      if (editingCat) {
        await updateCat.mutateAsync({ id: editingCat.id, ...vals as Partial<MenuCategoryRow> });
      } else {
        await createCat.mutateAsync({ name: (vals as { name: string }).name, stall_id: stallId, emoji: (vals as { emoji?: string }).emoji, sort_order: (vals as { sort_order?: number }).sort_order });
      }
      void msg.success(t("common.saved"));
      setCatModalOpen(false);
    } catch { void msg.error(t("menu.saveFailed")); }
  };

  // Table columns
  const columns: ColumnsType<MenuItem> = [
    {
      title: <span style={{ fontSize: 11, fontWeight: 700, letterSpacing: 0.5, color: T.textMuted }}>{t("menu.colHeaderItemName")}</span>,
      key: "name", width: 240,
      render: (_, row) => {
        const imgUrl = row.image_url;
        return (
          <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
            {imgUrl ? (
              <img src={imgUrl} alt={row.name} style={{ width: 52, height: 52, borderRadius: 10, objectFit: "cover", flexShrink: 0 }} />
            ) : (
              <div style={{ width: 52, height: 52, borderRadius: 10, background: T.surfaceSection, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 20, fontWeight: 700, color: T.textMuted, flexShrink: 0 }}>
                {row.name.slice(0, 1).toUpperCase()}
              </div>
            )}
            <div style={{ minWidth: 0 }}>
              <div style={{ fontSize: 14, fontWeight: 700, color: T.textDark, lineHeight: 1.3 }}>{row.name}</div>
              {row.description && <div style={{ fontSize: 12, color: T.textMuted, marginTop: 2, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", maxWidth: 150 }}>{row.description}</div>}
            </div>
          </div>
        );
      },
    },
    {
      title: <span style={{ fontSize: 11, fontWeight: 700, letterSpacing: 0.5, color: T.textMuted }}>{t("menu.colHeaderCategory")}</span>,
      key: "category", width: 160,
      render: (_, row) => {
        const r = row as MenuItem & { categories?: Array<{ id: string }>; category_ids?: string[] };
        const catIds = r.categories?.map(c => c.id) ?? r.category_ids ?? [];
        if (!catIds.length) return <Text style={{ color: T.borderLight }}>—</Text>;
        return (
          <div style={{ display: "flex", flexWrap: "wrap", gap: 4 }}>
            {catIds.map(id => {
              const cat = allCategories.find(c => c.id === id);
              return cat ? (
                <span key={id} style={{
                  display: "inline-block",
                  background: "#F5F5F5",
                  border: "1px solid #E5E7EB",
                  borderRadius: 20,
                  padding: "3px 12px",
                  fontSize: 12,
                  fontWeight: 500,
                  color: T.textBody,
                  whiteSpace: "nowrap",
                }}>
                  {cat.emoji ? `${cat.emoji} ` : ""}{cat.name}
                </span>
              ) : null;
            })}
          </div>
        );
      },
    },
    {
      title: <span style={{ fontSize: 11, fontWeight: 700, letterSpacing: 0.5, color: T.textMuted }}>{t("menu.colHeaderPriceRm")}</span>,
      key: "price", width: 120,
      render: (_, row) => {
        const offer = (row as MenuItem & { offer_price?: string }).offer_price;
        return (
          <div>
            <div style={{ fontSize: 14, fontWeight: 700, color: T.textDark }}>RM {Number(row.price).toFixed(2)}</div>
            {offer && <div style={{ fontSize: 11, color: T.textMuted, textDecoration: "line-through" }}>RM {parseFloat(offer).toFixed(2)}</div>}
          </div>
        );
      },
    },
    {
      title: <span style={{ fontSize: 11, fontWeight: 700, letterSpacing: 0.5, color: T.textMuted }}>{t("menu.colHeaderAvailability")}</span>,
      key: "available", width: 120,
      render: (_, row) => (
        <Switch
          checked={row.is_available}
          onChange={() => void onToggleAvailability(row)}
          style={{ background: row.is_available ? T.successBright : undefined }}
        />
      ),
    },
    {
      title: <span style={{ fontSize: 11, fontWeight: 700, letterSpacing: 0.5, color: T.textMuted }}>{t("menu.colHeaderLastUpdated")}</span>,
      key: "updated_at", width: 150,
      render: (_, row) => {
        const ts = (row as MenuItem & { updated_at?: string }).updated_at;
        if (!ts) return <Text style={{ color: T.borderLight }}>—</Text>;
        const d = dayjs(ts);
        const now = dayjs();
        const isToday = d.isSame(now, "day");
        const diffDays = now.diff(d, "day");
        let label: string;
        if (isToday) {
          label = t("menu.updatedToday", { time: d.format("hh:mm A") });
        } else if (diffDays === 1) {
          label = t("menu.updatedYesterday");
        } else if (diffDays < 7) {
          label = t("menu.updatedDaysAgo", { count: diffDays });
        } else {
          label = d.format("DD MMM YYYY");
        }
        return <span style={{ fontSize: 13, color: T.textBody }}>{label}</span>;
      },
    },
    {
      title: "", key: "actions", width: 50, fixed: "right",
      render: (_, row) => {
        const items: MenuProps["items"] = [
          { key: "edit",    label: t("common.edit"),            onClick: () => openEdit(row) },
          { key: "options", label: t("menu.manageOptions"),     onClick: () => setOptionsItemId(row.id) },
          {
            key: "delete",
            label: <span style={{ color: T.dangerText }}>{t("common.delete")}</span>,
            onClick: () => void onDelete(row.id),
          },
        ];
        return (
          <Dropdown menu={{ items }} trigger={["click"]}>
            <Button type="text" icon={<MoreOutlined />} style={{ padding: "0 8px" }} />
          </Dropdown>
        );
      },
    },
  ];

  return (
    <AdminShell>
      <div style={{ display: "flex", height: "100%", minHeight: "100vh", background: T.bg }}>

        {/* ── Left stall list panel ── */}
        <div style={{ width: 240, borderRight: "1px solid #E5E7EB", background: T.surface, flexShrink: 0, display: "flex", flexDirection: "column" }}>
          <div style={{ padding: "20px 16px 12px", fontSize: 11, fontWeight: 700, color: T.textMuted, letterSpacing: 0.8, textTransform: "uppercase" }}>
            {t("menu.yourStalls")}
          </div>
          <div style={{ flex: 1, overflowY: "auto" }}>
            {stalls.map(stall => {
              const isActive = stall.id === stallId;
              const itemCount = isActive ? items.length : null;
              return (
                <div
                  key={stall.id}
                  onClick={() => setStallId(stall.id)}
                  style={{
                    display: "flex", alignItems: "center", gap: 10,
                    padding: "10px 16px", cursor: "pointer",
                    background: isActive ? T.brandLight : "transparent",
                    borderLeft: isActive ? "3px solid #F97316" : "3px solid transparent",
                    transition: "background 0.15s",
                  }}
                >
                  {/* Stall avatar */}
                  {stall.cover_image ? (
                    <img src={stall.cover_image} alt={stall.name} style={{ width: 36, height: 36, borderRadius: 8, objectFit: "cover", flexShrink: 0 }} />
                  ) : (
                    <div style={{ width: 36, height: 36, borderRadius: 8, background: isActive ? "#FFEDD5" : T.surfaceSection, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 15, fontWeight: 700, color: isActive ? T.brand : T.textMuted, flexShrink: 0 }}>
                      {stall.name.slice(0, 1).toUpperCase()}
                    </div>
                  )}
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: 13, fontWeight: 600, color: isActive ? T.textDark : T.textBody, lineHeight: 1.3, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                      {stall.name}
                    </div>
                    <div style={{ display: "flex", alignItems: "center", gap: 4, marginTop: 2 }}>
                      <div style={{ width: 6, height: 6, borderRadius: "50%", background: stall.is_open ? T.successBright : T.textMuted }} />
                      <span style={{ fontSize: 11, color: stall.is_open ? T.successBright : T.textMuted, fontWeight: 600 }}>
                        {stall.is_open ? t("menu.stallBadgeActive") : t("menu.stallBadgePaused")}
                      </span>
                    </div>
                  </div>
                  {itemCount !== null && (
                    <span style={{ background: isActive ? T.brand : T.surfaceSection, color: isActive ? T.surface : T.textMuted, borderRadius: 20, padding: "1px 8px", fontSize: 11, fontWeight: 700, flexShrink: 0 }}>
                      {itemCount}
                    </span>
                  )}
                </div>
              );
            })}
          </div>
        </div>

        {/* ── Center content ── */}
        <div style={{ flex: 1, display: "flex", flexDirection: "column", minWidth: 0 }}>
          {/* Top bar */}
          <div style={{ padding: "16px 24px", borderBottom: "1px solid #E5E7EB", background: T.surface, display: "flex", alignItems: "center", justifyContent: "space-between" }}>
            <span style={{ fontSize: 18, fontWeight: 700, color: T.textDark }}>{t("menu.title")}</span>
            <Space>
              <Button
                icon={<UnorderedListOutlined />}
                onClick={() => setCatDrawerOpen(true)}
                disabled={!stallId}
              >
                {t("menu.manageCategories")}
              </Button>
              <Button
                type="primary"
                icon={<PlusOutlined />}
                onClick={openCreate}
                disabled={!stallId}
                style={{ background: T.brand, borderColor: T.brand, fontWeight: 600 }}
              >
                + {t("menu.addItem")}
              </Button>
            </Space>
          </div>

          {/* Content area */}
          <div style={{ flex: 1, padding: "24px", overflowY: "auto" }}>
            {!stallId ? (
              <div style={{ padding: 60, textAlign: "center", color: "#9CA3AF", fontSize: 15 }}>
                {t("menu.selectStallFromLeft")}
              </div>
            ) : (
              <>
                {/* Stall header */}
                <div style={{ marginBottom: 16 }}>
                  <div style={{ fontSize: 22, fontWeight: 800, color: T.textDark }}>
                    {selectedStall?.cover_image
                      ? <img src={selectedStall.cover_image} style={{ width: 28, height: 28, borderRadius: 6, objectFit: "cover", marginRight: 8, verticalAlign: "middle" }} alt="" />
                      : null
                    }
                    {selectedStall?.name ?? ""}
                  </div>
                  <div style={{ fontSize: 13, color: T.textMuted, marginTop: 4 }}>
                    {t("menu.managingSummary", {
                      items: t("menu.itemCount", { count: items.length }),
                      categories: t("menu.categoryCount", { count: categories.length }),
                    })}
                  </div>
                </div>

                {/* Items table */}
                <div style={{ background: T.surface, borderRadius: 12, border: "1px solid #E5E7EB", overflow: "hidden" }}>
                  <DataTable<MenuItem>
                    columns={columns}
                    dataSource={items}
                    loading={isLoading}
                    rowKey="id"
                    sticky={false}
                  />
                </div>
              </>
            )}
          </div>
        </div>

        {/* ── Right stall details panel ── */}
        {selectedStall && (
          <div style={{ width: 320, borderLeft: "1px solid #E5E7EB", background: T.surface, flexShrink: 0, display: "flex", flexDirection: "column" }}>
            {/* Header */}
            <div style={{ padding: "16px 20px", borderBottom: "1px solid #E5E7EB", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
              <span style={{ fontSize: 16, fontWeight: 700, color: T.textDark }}>{t("menu.stallPanelTitle")}</span>
            </div>

            <div style={{ flex: 1, overflowY: "auto", padding: "20px" }}>
              {/* Avatar — standalone large square */}
              <div style={{ marginBottom: 18 }}>
                <div style={{
                  width: 66, height: 66, borderRadius: 12,
                  background: T.statusPreparingBg, border: "1px solid #FED7AA",
                  display: "flex", alignItems: "center", justifyContent: "center",
                  fontSize: 30, overflow: "hidden", marginBottom: 12,
                }}>
                  {selectedStall.cover_image
                    ? <img src={selectedStall.cover_image} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                    : "🍜"
                  }
                </div>
                <div style={{ fontSize: 20, fontWeight: 800, color: T.textDark, lineHeight: 1.2 }}>{selectedStall.name}</div>
                <div style={{ fontSize: 12, color: T.textMuted, marginTop: 3 }}>
                  {t("menu.stallIdLabel", { id: selectedStall.id.slice(0, 8).toUpperCase() })}
                </div>
              </div>

              <Form
                form={stallForm}
                layout="vertical"
                onValuesChange={() => setStallDirty(true)}
              >
                {/* Stall Status card */}
                <div style={{ background: T.bg, borderRadius: 10, padding: "14px 16px", marginBottom: 20 }}>
                  <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 12 }}>
                    <span style={{ fontSize: 14, fontWeight: 700, color: T.textDark }}>{t("menu.stallStatusTitle")}</span>
                    <span style={{
                      background: selectedStall.is_open ? T.successDeep : T.surfaceSection,
                      color: selectedStall.is_open ? T.surface : T.textMuted,
                      borderRadius: 20, padding: "3px 12px",
                      fontSize: 11, fontWeight: 800, letterSpacing: 0.5,
                    }}>
                      {selectedStall.is_open ? t("menu.stallOnline") : t("menu.stallOffline")}
                    </span>
                  </div>
                  <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                    <span style={{ fontSize: 13, color: T.textBody }}>{t("menu.pauseOrdersHint")}</span>
                    <Form.Item name="is_open" valuePropName="checked" noStyle>
                      <Switch style={{ background: selectedStall.is_open ? T.successBright : undefined }} />
                    </Form.Item>
                  </div>
                </div>

                {/* Preparation Time */}
                <div style={{ marginBottom: 20 }}>
                  <div style={{ fontSize: 10, fontWeight: 800, color: T.textMuted, letterSpacing: 0.8, textTransform: "uppercase" as const, marginBottom: 8 }}>
                    {t("menu.prepTimeSection")}
                  </div>
                  <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                    <Form.Item name="prep_time" noStyle rules={[{ required: true, type: "number", min: 1, max: 120 }]}>
                      <InputNumber
                        min={1} max={120}
                        style={{ flex: 1, borderRadius: 8 }}
                      />
                    </Form.Item>
                    <span style={{ fontSize: 13, color: T.textBody, fontWeight: 500, flexShrink: 0 }}>{t("menu.prepTimeMins")}</span>
                  </div>
                </div>

                {/* Auto-Accept Orders */}
                <div style={{
                  display: "flex", alignItems: "center", justifyContent: "space-between",
                  paddingBottom: 18, marginBottom: 18, borderBottom: "1px solid #F3F4F6",
                }}>
                  <div>
                    <div style={{ fontSize: 14, fontWeight: 700, color: T.textDark }}>{t("menu.autoAcceptTitle")}</div>
                    <div style={{ fontSize: 12, color: T.textMuted, marginTop: 2 }}>{t("menu.autoAcceptHint")}</div>
                  </div>
                  <Form.Item name="auto_accept" valuePropName="checked" noStyle>
                    <Switch style={{ background: undefined }} />
                  </Form.Item>
                </div>

                {/* Opening Hours */}
                <div>
                  <div style={{ fontSize: 10, fontWeight: 800, color: T.textMuted, letterSpacing: 0.8, textTransform: "uppercase" as const, marginBottom: 12 }}>
                    {t("stalls.openingHours")}
                  </div>
                  {[
                    { label: t("stalls.weekdaysHours"), time: t("stalls.hoursWeekdayExample") },
                    { label: t("stalls.weekendHours"), time: t("stalls.hoursWeekendExample") },
                  ].map((row, i, arr) => (
                    <div key={row.label} style={{
                      display: "flex", justifyContent: "space-between", alignItems: "center",
                      paddingBottom: 12, marginBottom: i < arr.length - 1 ? 12 : 0,
                      borderBottom: i < arr.length - 1 ? "1px solid #F3F4F6" : "none",
                    }}>
                      <span style={{ fontSize: 13, fontWeight: 700, color: T.textDark }}>{row.label}</span>
                      <span style={{ fontSize: 13, color: T.textBody }}>{row.time}</span>
                    </div>
                  ))}
                </div>
              </Form>
            </div>

            {/* Footer buttons */}
            <div style={{ padding: "16px 20px", borderTop: "1px solid #E5E7EB", display: "flex", gap: 10 }}>
              <Button
                block
                style={{ borderRadius: 24, fontWeight: 600, height: 44 }}
                onClick={() => {
                  stallForm.setFieldsValue({
                    name: selectedStall.name,
                    description: selectedStall.description,
                    is_open: selectedStall.is_open,
                    prep_time: selectedStall.prep_time ?? 15,
                    auto_accept: selectedStall.auto_accept ?? false,
                  });
                  setStallDirty(false);
                }}
                disabled={!stallDirty}
              >
                {t("stalls.discard")}
              </Button>
              <Button
                block
                type="primary"
                style={{ borderRadius: 24, fontWeight: 700, height: 44, background: T.successDeep, borderColor: T.successDeep }}
                loading={updateStall.isPending}
                disabled={!stallDirty}
                onClick={() => void onSaveStall()}
              >
                {t("common.saveChanges")}
              </Button>
            </div>
          </div>
        )}
      </div>

      {/* ── Add/Edit Item Modal ── */}
      <Modal
        open={modalOpen}
        title={editing ? t("menu.editTitle") : t("menu.addTitle")}
        onCancel={() => setModalOpen(false)}
        onOk={() => void form.submit()}
        okText={t("common.save")}
        okButtonProps={{ style: { background: T.brandAmber, borderColor: T.brandAmber }, loading: createItem.isPending || updateItem.isPending }}
        width={640}
        destroyOnHidden
      >
        <Form form={form} layout="vertical" onFinish={onSave}>
          <Form.Item name="image_url" label={t("menu.formImage")}>
            <ImageUpload folder="menu" />
          </Form.Item>
          <Form.Item name="name" label={t("menu.formName")} rules={[{ required: true }]}>
            <Input />
          </Form.Item>
          <Form.Item name="description" label={t("menu.formDescription")}>
            <Input.TextArea rows={2} />
          </Form.Item>
          <Form.Item name="category_ids" label={t("menu.formCategoryId")}>
            <Select
              mode="multiple"
              allowClear
              placeholder={t("menu.formCategoryPlaceholder")}
              options={allCategories.map(c => ({ value: c.id, label: `${c.emoji ? c.emoji + " " : ""}${c.name}` }))}
              notFoundContent={
                <div style={{ textAlign: "center", padding: "8px 0", fontSize: 12, color: "#9CA3AF" }}>
                  {t("menu.addCategory")}
                </div>
              }
            />
          </Form.Item>
          <Form.Item name="price" label={t("menu.formPrice")} rules={[{ required: true }]}>
            <InputNumber prefix="RM" min={0} precision={2} style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item name="daily_stock" label={t("menu.formDailyStock")}>
            <InputNumber min={1} style={{ width: "100%" }} placeholder={t("menu.formDailyStockPlaceholder")} />
          </Form.Item>
          <Form.Item name="available_from" label={t("menu.formAvailableFrom")}>
            <Input placeholder={t("menu.formTimeAvailableFromPh")} maxLength={5} />
          </Form.Item>
          <Form.Item name="available_to" label={t("menu.formAvailableTo")}>
            <Input placeholder={t("menu.formTimeAvailableToPh")} maxLength={5} />
          </Form.Item>
          <Divider orientation="left" style={{ fontSize: 13, color: T.brandAmber }}>🏷 {t("menu.formOfferPrice")}</Divider>
          <Form.Item name="offer_price" label={t("menu.formOfferPrice")}>
            <InputNumber prefix="RM" min={0} precision={2} style={{ width: "100%" }} placeholder={t("menu.formOfferPricePlaceholder")} />
          </Form.Item>
          <Form.Item name="offer_from" label={t("menu.formOfferFrom")}>
            <Input placeholder={t("menu.formTimeOfferFromPh")} maxLength={5} />
          </Form.Item>
          <Form.Item name="offer_to" label={t("menu.formOfferTo")}>
            <Input placeholder={t("menu.formTimeOfferToPh")} maxLength={5} />
          </Form.Item>
          <Divider />
          <Form.Item name="is_available" label={t("menu.formIsAvailable")} valuePropName="checked" initialValue={true}>
            <Switch checkedChildren={t("common.yes")} unCheckedChildren={t("common.no")} />
          </Form.Item>
          <Form.Item name="sort_order" label={t("menu.formSortOrder")} initialValue={0}>
            <InputNumber min={0} style={{ width: "100%" }} />
          </Form.Item>
        </Form>
      </Modal>

      {/* ── Option Groups Drawer ── */}
      <OptionGroupsDrawer
        open={!!optionsItemId}
        item={optionsItem}
        onClose={() => setOptionsItemId(null)}
      />

      {/* ── Categories Drawer ── */}
      <Drawer
        open={catDrawerOpen}
        title={t("menu.manageCategories")}
        onClose={() => setCatDrawerOpen(false)}
        width={480}
        extra={
          <Button type="primary" icon={<PlusOutlined />}
            onClick={() => { setEditingCat(null); catForm.resetFields(); setCatModalOpen(true); }}
            style={{ background: T.brandAmber, borderColor: T.brandAmber }}
          >
            {t("menu.addCategory")}
          </Button>
        }
      >
        {categories.map(cat => (
          <div key={cat.id} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "8px 4px", borderBottom: "1px solid #F3F4F6" }}>
            <Text>{cat.emoji ? `${cat.emoji} ` : ""}{cat.name}</Text>
            <Space>
              <Button size="small" icon={<EditOutlined />} onClick={() => {
                setEditingCat(cat);
                catForm.setFieldsValue(cat);
                setCatModalOpen(true);
              }} />
              <Popconfirm title={t("common.confirmDelete")} onConfirm={() => void deleteCat.mutateAsync({ id: cat.id })} okType="danger">
                <Button size="small" danger icon={<DeleteOutlined />} />
              </Popconfirm>
            </Space>
          </div>
        ))}
      </Drawer>

      <Modal
        open={catModalOpen}
        title={editingCat ? t("common.edit") : t("menu.addCategory")}
        onCancel={() => setCatModalOpen(false)}
        onOk={() => void saveCat()}
        okText={t("common.save")}
        okButtonProps={{ loading: createCat.isPending || updateCat.isPending, style: { background: T.brandAmber, borderColor: T.brandAmber } }}
        destroyOnHidden
      >
        <Form form={catForm} layout="vertical">
          <Form.Item name="emoji" label={t("menu.formCategoryEmoji")}>
            <Input placeholder={t("menu.formCategoryEmojiPlaceholder")} maxLength={4} />
          </Form.Item>
          <Form.Item name="name" label={t("menu.formCategoryName")} rules={[{ required: true }]}>
            <Input />
          </Form.Item>
          <Form.Item name="sort_order" label={t("menu.formSortOrder")} initialValue={0}>
            <InputNumber min={0} style={{ width: "100%" }} />
          </Form.Item>
        </Form>
      </Modal>
    </AdminShell>
  );
}
