import { Form, Input, Button } from "antd";
import { LockOutlined, UserOutlined } from "@ant-design/icons";
import { useNavigate } from "react-router-dom";
import { message } from "antd";
import { useTranslation } from "react-i18next";
import { useAdminLogin } from "../api/hooks";
import { tokens } from "../styles/tokens";
const { color: T } = tokens;
import { useAuthStore } from "../store/auth";

interface LoginForm { email: string; password: string }

export function LoginScreen() {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const login = useAdminLogin();
  const { setTokens, setStaff } = useAuthStore();
  const [form] = Form.useForm<LoginForm>();

  const onFinish = async (values: LoginForm) => {
    try {
      const res = await login.mutateAsync(values);
      setTokens(res.data.tokens.accessToken, res.data.tokens.refreshToken);
      setStaff({
        id: res.data.admin.id,
        name: res.data.admin.name,
        role: res.data.admin.role,
        kopitiamId: res.data.admin.kopitiam_id,
      });
      void navigate("/");
    } catch {
      void message.error(t("auth.loginErrorDetail"));
    }
  };

  return (
    <div style={{
      minHeight: "100vh",
      background: T.bg,
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      fontFamily: "inherit",
    }}>
      {/* Two-panel card */}
      <div style={{
        display: "flex",
        borderRadius: 20,
        overflow: "hidden",
        boxShadow: "0 8px 48px rgba(0,0,0,0.10)",
        width: 820,
        minHeight: 500,
        background: T.surface,
      }}>
        {/* Left — branding panel */}
        <div style={{
          width: 340,
          background: "linear-gradient(160deg, #1C1C1C 0%, #2D1B00 100%)",
          padding: "48px 40px",
          display: "flex",
          flexDirection: "column",
          justifyContent: "space-between",
          flexShrink: 0,
        }}>
          {/* Logo */}
          <div>
            <div style={{
              width: 52, height: 52, borderRadius: 14,
              background: T.brand,
              display: "flex", alignItems: "center", justifyContent: "center",
              fontSize: 26, marginBottom: 24,
            }}>
              ☕
            </div>
            <div style={{ fontSize: 22, fontWeight: 900, color: T.surface, marginBottom: 6, letterSpacing: -0.3 }}>
              {t("auth.brandName")}
            </div>
            <div style={{ fontSize: 13, color: T.textMuted, lineHeight: 1.6 }}>
              {t("auth.brandTagline")}
            </div>
          </div>

          {/* Feature list */}
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            {[
              { icon: "📦", text: t("auth.featureOrder") },
              { icon: "👥", text: t("auth.featureStaff") },
              { icon: "📊", text: t("auth.featureReports") },
              { icon: "⚙️", text: t("auth.featureSettings") },
            ].map(f => (
              <div key={f.text} style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <span style={{ fontSize: 16 }}>{f.icon}</span>
                <span style={{ fontSize: 13, color: T.borderLight }}>{f.text}</span>
              </div>
            ))}
          </div>

          <div style={{ fontSize: 11, color: T.textBody }}>{t("auth.copyright")}</div>
        </div>

        {/* Right — form panel */}
        <div style={{
          flex: 1,
          padding: "52px 48px",
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
        }}>
          <div style={{ marginBottom: 36 }}>
            <div style={{ fontSize: 26, fontWeight: 900, color: T.textDark, marginBottom: 6 }}>
              {t("auth.welcomeBack")}
            </div>
            <div style={{ fontSize: 14, color: T.textMuted }}>
              {t("auth.signInSubtitle")}
            </div>
          </div>

          <Form form={form} layout="vertical" onFinish={onFinish} autoComplete="off">
            <Form.Item
              name="email"
              label={<span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, color: T.textMuted }}>{t("auth.emailLabel").toUpperCase()}</span>}
              rules={[{ required: true, message: t("auth.emailRequired") }, { type: "email", message: t("auth.emailInvalid") }]}
              style={{ marginBottom: 18 }}
            >
              <Input
                prefix={<UserOutlined style={{ color: T.textMuted }} />}
                placeholder={t("auth.emailPlaceholder")}
                style={{ height: 48, borderRadius: 12, fontSize: 14 }}
              />
            </Form.Item>

            <Form.Item
              name="password"
              label={<span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, color: T.textMuted }}>{t("auth.passwordLabel").toUpperCase()}</span>}
              rules={[{ required: true, message: t("auth.passwordRequired") }]}
              style={{ marginBottom: 28 }}
            >
              <Input.Password
                prefix={<LockOutlined style={{ color: T.textMuted }} />}
                placeholder={t("auth.passwordPlaceholder")}
                style={{ height: 48, borderRadius: 12, fontSize: 14 }}
              />
            </Form.Item>

            <Form.Item style={{ marginBottom: 0 }}>
              <Button
                htmlType="submit"
                loading={login.isPending}
                block
                style={{
                  height: 50,
                  borderRadius: 12,
                  fontSize: 16,
                  fontWeight: 700,
                  background: T.brand,
                  borderColor: T.brand,
                  color: T.surface,
                  letterSpacing: 0.2,
                }}
              >
                {t("auth.signInBtn")}
              </Button>
            </Form.Item>
          </Form>

          {import.meta.env.DEV && (
            <div style={{
              marginTop: 24,
              padding: "12px 16px",
              background: T.brandLight,
              border: "1px solid #FED7AA",
              borderRadius: 10,
              fontSize: 12,
              color: T.brandAmberText,
              lineHeight: 1.8,
            }}>
              <strong style={{ display: "block", marginBottom: 4 }}>{t("auth.demoCredentials")}</strong>
              <span style={{ fontFamily: "monospace" }}>
                {t("auth.demoSuperLine", { email: "admin@kawkaw.my", password: "Admin@Kawkaw1" })}
              </span>
              <br />
              <span style={{ fontFamily: "monospace" }}>
                {t("auth.demoAdminLine", { email: "admin2@kawkaw.my", password: "Admin@Kawkaw2" })}
              </span>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
