import { useEffect } from "react";
import { useTranslation } from "react-i18next";
import { Modal, Button, Divider } from "antd";
import i18n from "../i18n";
import {
  DownloadOutlined,
  PrinterOutlined,
  CloseOutlined,
  ShopOutlined,
  CarOutlined,
  ShoppingOutlined,
} from "@ant-design/icons";
import { formatDateOnly, formatDateTimeDetail } from "../utils/formatLocaleDate";
import { tokens } from "../styles/tokens";
const { color: T } = tokens;
import type { TxnDetail } from "../api/hooks";

// ─── Types ──────────────────────────────────────────────────────────────────

export type ReceiptTxn = TxnDetail & {
  order: TxnDetail["order"] & {
    kopitiam: { name: string; address: string; phone: string };
    items: Array<{ id: string; name: string; qty: number; price: string; options: unknown }>;
  };
};

interface Props {
  open: boolean;
  onClose: () => void;
  txn: ReceiptTxn;
}

// ─── Constants ──────────────────────────────────────────────────────────────

const RECEIPT_PAY_KEYS: Record<string, string> = {
  visa: "receipt.payVisa",
  fpx: "receipt.payFpx",
  grabpay: "receipt.payGrab",
  cash: "receipt.payCash",
  ewallet: "receipt.payEwallet",
  tng: "receipt.payTng",
  boost: "receipt.payBoost",
};

function receiptChannelLabel(type: string, t: (k: string) => string): string {
  if (type === "delivery") return t("receipt.channelDelivery");
  if (type === "pickup") return t("receipt.channelPickup");
  return t("receipt.channelOther");
}

const TEAL = T.tealDark;
const RECEIPT_ID = "kawkaw-receipt-printable";

// ─── Helpers ────────────────────────────────────────────────────────────────

function parseOptions(raw: unknown): string {
  if (!raw) return "";
  try {
    const arr = typeof raw === "string" ? (JSON.parse(raw) as unknown[]) : (raw as unknown[]);
    if (!Array.isArray(arr) || arr.length === 0) return "";
    return arr
      .map((o) => {
        if (typeof o === "string") return o;
        if (typeof o === "object" && o !== null) {
          const obj = o as Record<string, unknown>;
          return (obj["label"] ?? obj["name"] ?? obj["value"] ?? String(o)) as string;
        }
        return String(o);
      })
      .join(", ");
  } catch {
    return "";
  }
}

function MetaLabel({ children }: { children: React.ReactNode }) {
  return (
    <div
      style={{
        fontSize: 9,
        fontWeight: 700,
        color: TEAL,
        letterSpacing: 0.6,
        textTransform: "uppercase",
        marginBottom: 2,
      }}
    >
      {children}
    </div>
  );
}

function TotalRow({
  label,
  value,
  accent,
  bold,
  large,
}: {
  label: string;
  value: string;
  accent?: boolean;
  bold?: boolean;
  large?: boolean;
}) {
  const color = accent ? T.tealMid : T.textDark;
  return (
    <div style={{ display: "flex", justifyContent: "space-between", gap: 64, minWidth: 220 }}>
      <span style={{ fontSize: large ? 11 : 12, fontWeight: bold ? 700 : 400, color, letterSpacing: bold ? 0.5 : 0, textTransform: bold ? "uppercase" : "none" }}>
        {label}
      </span>
      <span style={{ fontSize: large ? 16 : 12, fontWeight: bold ? 800 : 400, color }}>
        {value}
      </span>
    </div>
  );
}

function BarcodeDecoration({ code }: { code: string }) {
  const bars = [1, 2, 1, 1, 3, 1, 2, 1, 1, 2, 3, 1, 1, 2, 1, 2, 1, 1, 3, 1, 1, 2, 1, 1, 2, 3, 1, 2, 1, 1, 2, 1, 1, 3, 1, 1, 2, 1, 2, 1];
  const GAP = 2;
  const UNIT = 1.5;
  const H = 40;

  // Pre-compute bar positions so SVG rects can be placed exactly
  let cursor = 0;
  const segments = bars.map((w, i) => {
    const seg = { x: cursor, w: w * UNIT, opacity: i % 5 === 4 ? 0.3 : 1 };
    cursor += w * UNIT + GAP;
    return seg;
  });
  const svgWidth = cursor - GAP; // trim trailing gap

  return (
    <div style={{ textAlign: "center" }}>
      {/* SVG rects render in every PDF/print without needing "Print background graphics" */}
      <svg
        width={svgWidth}
        height={H}
        style={{ display: "block", margin: "0 auto" }}
        aria-hidden="true"
      >
        {segments.map((s, i) => (
          <rect
            key={i}
            x={s.x}
            y={0}
            width={s.w}
            height={H}
            fill={T.receiptBg}
            fillOpacity={s.opacity}
          />
        ))}
      </svg>
      <div
        style={{
          fontSize: 9,
          color: T.textMuted,
          marginTop: 6,
          letterSpacing: 2,
          fontVariantNumeric: "tabular-nums",
        }}
      >
        {code}
      </div>
    </div>
  );
}

// ─── Receipt card content (also used for print) ─────────────────────────────

function ReceiptContent({ txn }: { txn: ReceiptTxn }) {
  const { t } = useTranslation();
  const kop = txn.order.kopitiam;
  const order = txn.order;

  const totalRefunded = txn.refunds
    .filter((r) => r.status === "completed" || r.status === "approved")
    .reduce((sum, r) => sum + Number(r.amount), 0);

  const latestRefund = txn.refunds.find(
    (r) => r.status === "completed" || r.status === "approved",
  );

  const receiptCode = txn.reference
    ? txn.reference.toUpperCase()
    : `TXN-${txn.id.slice(0, 12).toUpperCase()}`;

  const barcodeNum = `${txn.id.slice(0, 10)}-${order.order_code}`.toUpperCase();

  const addressLines = kop.address.split(",").map((s) => s.trim()).filter(Boolean);

  return (
    <div>
      {/* ── Header ── */}
      <div style={{ textAlign: "center", marginBottom: 20 }}>
        <div
          style={{
            width: 44,
            height: 44,
            background: T.receiptBg,
            borderRadius: 10,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            margin: "0 auto 12px",
          }}
        >
          <ShopOutlined style={{ color: T.surface, fontSize: 22 }} />
        </div>
        <div
          style={{
            fontSize: 18,
            fontWeight: 800,
            letterSpacing: 1.5,
            textTransform: "uppercase",
            color: T.receiptBg,
          }}
        >
          {kop.name}
        </div>
        <div style={{ fontSize: 11, color: T.textBody, marginTop: 6, lineHeight: 1.7 }}>
          {addressLines.slice(0, 2).join(", ")}
          {addressLines.length > 2 && (
            <>
              <br />
              {addressLines.slice(2).join(", ")}
            </>
          )}
        </div>
        <div style={{ fontSize: 11, color: T.textBody, marginTop: 2 }}>
          {t("receipt.tel")} {kop.phone}
        </div>
      </div>

      <Divider style={{ margin: "0 0 14px" }} />

      {/* ── Receipt meta ── */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 1fr",
          gap: "12px 16px",
          marginBottom: 14,
        }}
      >
        <div>
          <MetaLabel>{t("receipt.metaReceiptNo")}</MetaLabel>
          <div style={{ fontSize: 13, fontWeight: 700 }}>{receiptCode}</div>
        </div>
        <div style={{ textAlign: "right" }}>
          <MetaLabel>{t("receipt.metaOrderId")}</MetaLabel>
          <div style={{ fontSize: 13, fontWeight: 700 }}>#{order.order_code}</div>
        </div>
        <div>
          <MetaLabel>{t("receipt.metaDateTime")}</MetaLabel>
          <div style={{ fontSize: 12 }}>
            {txn.paid_at ? formatDateTimeDetail(txn.paid_at, i18n.language) : "—"}
          </div>
        </div>
        <div style={{ textAlign: "right" }}>
          <MetaLabel>{t("receipt.metaPaymentMethod")}</MetaLabel>
          <div style={{ fontSize: 12 }}>
            {(() => {
              const payKey = RECEIPT_PAY_KEYS[txn.method];
              return payKey ? t(payKey) : txn.method.toUpperCase();
            })()}
          </div>
        </div>
      </div>

      <Divider style={{ margin: "0 0 14px" }} />

      {/* ── Customer + channel ── */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr auto",
          gap: 8,
          marginBottom: 14,
          alignItems: "start",
        }}
      >
        <div>
          <MetaLabel>{t("receipt.metaCustomerName")}</MetaLabel>
          <div style={{ fontSize: 14, fontWeight: 600 }}>
            {order.customer?.name ?? t("common.guest")}
          </div>
        </div>
        <div style={{ textAlign: "right" }}>
          <MetaLabel>{t("receipt.metaOrderChannel")}</MetaLabel>
          <div style={{ marginTop: 4 }}>
            <span
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: 5,
                background: T.surfaceSection,
                borderRadius: 20,
                padding: "3px 10px",
                fontSize: 11,
                fontWeight: 600,
                color: T.siderHover,
              }}
            >
              {order.type === "delivery" ? (
                <CarOutlined style={{ fontSize: 10 }} />
              ) : (
                <ShoppingOutlined style={{ fontSize: 10 }} />
              )}
              {receiptChannelLabel(order.type, t)}
            </span>
          </div>
        </div>
      </div>

      <Divider style={{ margin: "0 0 14px" }} />

      {/* ── Items table ── */}
      <div style={{ marginBottom: 14 }}>
        {/* Header row */}
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "1fr 36px 60px 68px",
            gap: "4px 8px",
            borderBottom: "1.5px solid #E5E7EB",
            paddingBottom: 6,
            marginBottom: 8,
          }}
        >
          {[t("receipt.colItemName"), t("receipt.colQty"), t("receipt.colPriceRm"), t("receipt.colSubtotalRm")].map((h, i) => (
            <div
              key={h}
              style={{
                fontSize: 9,
                fontWeight: 700,
                color: T.textBody,
                letterSpacing: 0.5,
                textTransform: "uppercase",
                textAlign: i === 0 ? "left" : "right",
              }}
            >
              {h}
            </div>
          ))}
        </div>

        {/* Item rows */}
        {order.items.map((item) => {
          const opts = parseOptions(item.options);
          const subtotal = (Number(item.price) * item.qty).toFixed(2);
          return (
            <div
              key={item.id}
              style={{
                display: "grid",
                gridTemplateColumns: "1fr 36px 60px 68px",
                gap: "2px 8px",
                marginBottom: 10,
              }}
            >
              <div>
                <div style={{ fontSize: 12, fontWeight: 700 }}>{item.name}</div>
                {opts && (
                  <div style={{ fontSize: 10, color: T.successBright, marginTop: 1 }}>
                    {t("receipt.optionsPlus")} {opts}
                  </div>
                )}
              </div>
              <div style={{ fontSize: 12, textAlign: "right", paddingTop: 1 }}>{item.qty}</div>
              <div style={{ fontSize: 12, textAlign: "right", paddingTop: 1 }}>
                {Number(item.price).toFixed(2)}
              </div>
              <div style={{ fontSize: 12, textAlign: "right", paddingTop: 1 }}>{subtotal}</div>
            </div>
          );
        })}
      </div>

      <Divider style={{ margin: "0 0 14px" }} />

      {/* ── Totals ── */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: 6,
          alignItems: "flex-end",
          marginBottom: 14,
        }}
      >
        <TotalRow label={t("receipt.subtotal")} value={`RM ${Number(order.subtotal).toFixed(2)}`} />
        {Number(order.delivery_fee) > 0 && (
          <TotalRow
            label={t("receipt.deliveryFee")}
            value={`RM ${Number(order.delivery_fee).toFixed(2)}`}
          />
        )}
        {Number(order.sst_amount) > 0 && (
          <TotalRow
            label={t("receipt.sstPct", {
              pct: Math.round(Number(order.subtotal) > 0 ? Number(order.sst_amount) / Number(order.subtotal) * 100 : 0),
            })}
            value={`RM ${Number(order.sst_amount).toFixed(2)}`}
          />
        )}
        {Number(order.voucher_discount) > 0 && (
          <TotalRow
            label={t("receipt.discount")}
            value={`– RM ${Number(order.voucher_discount).toFixed(2)}`}
            accent
          />
        )}
        <div
          style={{
            borderTop: "1.5px solid #E5E7EB",
            paddingTop: 10,
            marginTop: 4,
            width: "100%",
            display: "flex",
            justifyContent: "flex-end",
          }}
        >
          <TotalRow
            label={t("receipt.totalPaid")}
            value={`RM ${Number(txn.amount).toFixed(2)}`}
            bold
            large
          />
        </div>
      </div>

      {/* ── Refund section ── */}
      {totalRefunded > 0 && latestRefund && (
        <>
          <Divider style={{ margin: "0 0 14px" }} />
          <div
            style={{
              borderLeft: "3px solid #F97316",
              paddingLeft: 12,
              display: "grid",
              gridTemplateColumns: "1fr 1fr",
              gap: 8,
              marginBottom: 14,
            }}
          >
            <div>
              <MetaLabel>{t("receipt.refundedAmount")}</MetaLabel>
              <div style={{ fontSize: 15, fontWeight: 800, color: T.brand }}>
                RM {totalRefunded.toFixed(2)}
              </div>
            </div>
            <div style={{ textAlign: "right" }}>
              <MetaLabel>{t("receipt.refundDate")}</MetaLabel>
              <div style={{ fontSize: 12 }}>
                {formatDateOnly(latestRefund.created_at, i18n.language)}
              </div>
            </div>
          </div>
        </>
      )}

      <Divider style={{ margin: "0 0 16px" }} />

      {/* ── Footer ── */}
      <div style={{ textAlign: "center" }}>
        <div style={{ fontSize: 13, fontWeight: 600, color: T.receiptBg, marginBottom: 4 }}>
          {t("receipt.thankYou")}
        </div>
        <div
          style={{
            fontSize: 9,
            color: T.textMuted,
            letterSpacing: 1.2,
            textTransform: "uppercase",
            marginBottom: 18,
          }}
        >
          {t("receipt.systemGenerated")}
        </div>
        <BarcodeDecoration code={barcodeNum} />
      </div>
    </div>
  );
}

// ─── Print helper ────────────────────────────────────────────────────────────

function printReceipt(receiptId: string) {
  const el = document.getElementById(receiptId);
  if (!el) return;
  const win = window.open("", "_blank", "width=320,height=800");
  if (!win) return;
  const docTitle = i18n.t("receipt.printTitle");
  // @page rule MUST be in the original stylesheet — Chrome does not pick up
  // @page from DOM-appended <style> elements. We put it at rule index 0 with
  // a conservative fallback height (220mm covers even long receipts), then
  // update it via CSSOM after fonts load to get the exact content height.
  win.document.write(`<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8"/>
  <title>${docTitle}</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@400;500;600;700&display=block" rel="stylesheet">
  <style>
    @page { size: 80mm 220mm; margin: 8mm; }
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body {
      font-family: "Noto Sans SC", -apple-system, BlinkMacSystemFont,
                   "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
      padding: 12px;
      color: #1A1A1A;
    }
    hr { border: none; border-top: 1px solid #E5E7EB; margin: 10px 0; }
    svg { vertical-align: middle; }
  </style>
</head>
<body>${el.innerHTML}</body>
</html>`);
  win.document.close();
  win.focus();
  Promise.all([
    win.document.fonts.load('400 12px "Noto Sans SC"'),
    win.document.fonts.load('700 12px "Noto Sans SC"'),
  ]).then(() => {
    // Measure actual content height and update @page via CSSOM.
    // CSSOM mutations are picked up by Chrome's print engine; DOM mutations are not.
    try {
      const PX_TO_MM = 25.4 / 96;
      const contentMm = Math.ceil(win.document.body.scrollHeight * PX_TO_MM);
      const pageH = contentMm + 16; // 8mm top + 8mm bottom margin
      const sheet = win.document.styleSheets[0] as CSSStyleSheet;
      sheet.deleteRule(0); // remove @page { size: 80mm 220mm }
      sheet.insertRule(`@page { size: 80mm ${pageH}mm; margin: 8mm; }`, 0);
    } catch (_) {
      // CSSOM update failed — static 220mm fallback remains in effect
    }
    win.print();
    win.close();
  }).catch(() => {
    win.print();
    win.close();
  });
}

// ─── Modal ──────────────────────────────────────────────────────────────────

export function ReceiptModal({ open, onClose, txn }: Props) {
  const { t } = useTranslation();
  // Inject print style so Ant Design modal doesn't show during page-level print
  useEffect(() => {
    const id = "receipt-modal-print-style";
    if (document.getElementById(id)) return;
    const style = document.createElement("style");
    style.id = id;
    style.textContent = `@media print { body > * { display: none !important; } #${RECEIPT_ID} { display: block !important; } }`;
    document.head.appendChild(style);
    return () => { document.getElementById(id)?.remove(); };
  }, []);

  return (
    <Modal
      open={open}
      onCancel={onClose}
      footer={null}
      width={520}
      centered
      destroyOnHidden
      styles={{
        body: { padding: "0 0 16px" },
        content: { borderRadius: 16, padding: 0, overflow: "hidden" },
      }}
      closable={false}
    >
      {/* Scrollable receipt area */}
      <div
        style={{
          maxHeight: "70vh",
          overflowY: "auto",
          padding: "28px 32px 4px",
        }}
      >
        <div id={RECEIPT_ID}>
          <ReceiptContent txn={txn} />
        </div>
      </div>

      {/* Action bar */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          gap: 12,
          padding: "16px 32px 0",
          borderTop: "1px solid #F3F4F6",
        }}
      >
        <Button
          icon={<DownloadOutlined />}
          onClick={() => printReceipt(RECEIPT_ID)}
          style={{ borderRadius: 24, height: 40, paddingInline: 20, fontWeight: 600 }}
        >
          {t("receipt.downloadPdf")}
        </Button>
        <Button
          type="primary"
          icon={<PrinterOutlined />}
          onClick={() => printReceipt(RECEIPT_ID)}
          style={{
            borderRadius: 24,
            height: 40,
            paddingInline: 20,
            fontWeight: 600,
            background: T.receiptBg,
            borderColor: T.receiptBg,
          }}
        >
          {t("receipt.printReceipt")}
        </Button>
        <Button
          type="text"
          icon={<CloseOutlined />}
          onClick={onClose}
          style={{ fontWeight: 600, color: T.textBody }}
        >
          {t("receipt.close")}
        </Button>
      </div>
    </Modal>
  );
}
