const GROUP_ICON_LABEL_KEY: Record<string, string> = {
  sugar: "addMenuItem.groupIconSugar",
  ice: "addMenuItem.groupIconIce",
  special: "addMenuItem.groupIconSpecial",
};

function GroupIcon({ iconKey, size = 16, color = "currentColor" }: { iconKey: string; size?: number; color?: string }) {
  const icon = GROUP_ICON_DEFS.find(i => i.key === iconKey);
  if (!icon) return null;
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox={icon.viewBox} fill="none" style={{ display: "block" }}>
      {icon.paths.map((d, i) => <path key={i} d={d} fill={color} />)}
    </svg>
  );
}

/* ─── Local types for inline customization ──────────────── */
type LocalChoice = {
  localId: string;
  label: string;
  extra_charge: number;
  isDefault: boolean;
  input_type: "radio" | "input" | "textarea";
};

type LocalGroup = {
  localId: string;
  name: string;
  icon_key?: string;      // "sugar" | "ice" | "special"
  required: boolean;
  selection: "single" | "multiple";
  min_select: number;
  max_select: number;
  choices: LocalChoice[];
};

/* ─── Section header ────────────────────────────────────── */
function SectionHead({ num, label }: { num: string; label: string }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 20 }}>
      <span style={{
        width: 26, height: 26, borderRadius: "50%",
        background: "#F97316", color: "#fff",
        fontSize: 12, fontWeight: 800,
        display: "inline-flex", alignItems: "center", justifyContent: "center",
        flexShrink: 0,
      }}>{num}</span>
      <span style={{ fontSize: 16, fontWeight: 800, color: "#212121" }}>{label}</span>
    </div>
  );
}

/* ─── Customer Preview card ──────────────────────────────── */
function PreviewCard({
  name, price, imageUrl, isAvailable,
}: { name?: string; price?: number; imageUrl?: string; isAvailable?: boolean }) {
  const { t } = useTranslation();
  const available = isAvailable !== false;
  return (
    <div style={{ borderRadius: 16, border: "1px solid #E5E7EB", overflow: "hidden", background: "#fff" }}>
      {/* Image area */}
      <div style={{
        position: "relative", height: 160,
        background: imageUrl ? undefined : "#2D2D2D",
        display: "flex", alignItems: "flex-end", justifyContent: "space-between",
        padding: "8px 12px",
      }}>
        {imageUrl && (
          <img
            src={imageUrl} alt=""
            style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }}
          />
        )}
        <span style={{
          position: "relative",
          background: available ? "#16A34A" : "#9E9E9E",
          color: "#fff", fontSize: 10, fontWeight: 800, letterSpacing: 0.5,
          borderRadius: 20, padding: "3px 10px",
        }}>
          {available ? t("addMenuItem.badgeAvailable") : t("addMenuItem.badgeUnavailable")}
        </span>
        <span style={{
          position: "relative",
          background: "#F97316", color: "#fff",
          fontSize: 14, fontWeight: 800,
          borderRadius: 8, padding: "3px 10px",
        }}>
          RM {price != null ? Number(price).toFixed(2) : "0.00"}
        </span>
      </div>

      {/* Info */}
      <div style={{ padding: "14px 16px" }}>
        <div style={{ fontSize: 15, fontWeight: 800, color: name ? "#212121" : "#D1D5DB", marginBottom: 6 }}>
          {name || t("addMenuItem.previewNameFallback")}
        </div>
        <div style={{ fontSize: 12, color: "#9E9E9E", marginBottom: 14, lineHeight: 1.5 }}>
          {t("addMenuItem.previewDescHint")}
        </div>
        <div style={{
          display: "flex", justifyContent: "space-between", alignItems: "center",
          paddingTop: 10, borderTop: "1px solid #F3F4F6",
        }}>
          <span style={{ fontSize: 13, color: "#616161" }}>{t("addMenuItem.customizeYourOrder")}</span>
          <span style={{ color: "#9E9E9E", fontSize: 16 }}>›</span>
        </div>
      </div>
    </div>
  );
}

/* ─── Main screen ────────────────────────────────────────── */
export function AddMenuItemScreen() {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const location = useLocation();
  const { message: msg } = App.useApp();

  const selectionOptions = useMemo(
    () => [
      { value: "single" as const, label: t("addMenuItem.selectionSingle") },
      { value: "multiple" as const, label: t("addMenuItem.selectionMultiple") },
    ],
    [t],
  );
  const inputTypeOptions = useMemo(
    () => [
      { value: "radio" as const, label: t("addMenuItem.typeRadio") },
      { value: "input" as const, label: t("addMenuItem.typeInput") },
      { value: "textarea" as const, label: t("addMenuItem.typeTextarea") },
    ],
    [t],
  );

  const initStallId = (location.state as { stallId?: string } | null)?.stallId;
  const [selectedStallId, setSelectedStallId] = useState<string | undefined>(initStallId);

  const [form] = Form.useForm();
  const createItem = useCreateMenuItem();
  const createGroup = useCreateOptionGroup();
  const createChoice = useCreateOptionChoice();

  const [custEnabled, setCustEnabled] = useState(false);
  const [groups, setGroups] = useState<LocalGroup[]>([]);

  const newUid = () => Math.random().toString(36).slice(2, 10);
  const addGroup = () => setGroups(g => [...g, {
    localId: newUid(), name: "", icon_key: undefined, required: false, selection: "single" as const, min_select: 0, max_select: 1, choices: [],
  }]);
  const updateGroup = (id: string, patch: Partial<LocalGroup>) =>
    setGroups(g => g.map(x => x.localId === id ? { ...x, ...patch } : x));
  const removeGroup = (id: string) => setGroups(g => g.filter(x => x.localId !== id));
  const addChoice = (groupId: string) =>
    setGroups(g => g.map(x => x.localId !== groupId ? x : {
      ...x, choices: [...x.choices, { localId: newUid(), label: "", extra_charge: 0, isDefault: false, input_type: "radio" as const }],
    }));
  const updateChoice = (groupId: string, choiceId: string, patch: Partial<LocalChoice>) =>
    setGroups(g => g.map(x => x.localId !== groupId ? x : {
      ...x, choices: x.choices.map(c => c.localId === choiceId ? { ...c, ...patch } : c),
    }));
  const removeChoice = (groupId: string, choiceId: string) =>
    setGroups(g => g.map(x => x.localId !== groupId ? x : {
      ...x, choices: x.choices.filter(c => c.localId !== choiceId),
    }));

  const { data: stallsRes } = useAdminStalls();
  const stalls: Stall[] = stallsRes?.data ?? [];
  const selectedStall = stalls.find(s => s.id === selectedStallId) ?? null;

  const { data: catRes } = useAdminMenuCategories(selectedStallId);
  const categories: MenuCategoryRow[] = catRes?.data ?? [];

  /* live preview via Form.useWatch */
  const previewName = Form.useWatch("name", { form, preserve: true }) as string | undefined;
  const previewPrice = Form.useWatch("price", { form, preserve: true }) as number | undefined;
  const previewImage = Form.useWatch("image_url", { form, preserve: true }) as string | undefined;
  const isAvailable = Form.useWatch("is_available", { form, preserve: true }) as boolean | undefined;

  /* required fields for "all mandatory fields completed" indicator */
  const mandatoryComplete = !!(previewName && selectedStallId && previewPrice != null && previewPrice >= 0);

  const doSave = async (values: Record<string, unknown>) => {
    const result = await createItem.mutateAsync({ ...values, stall_id: selectedStallId }) as { data: { id: string } };
    const itemId = result?.data?.id;
    if (itemId && custEnabled && groups.length > 0) {
      let gi = 0;
      for (const g of groups) {
        if (!g.name.trim()) { gi++; continue; }
        const gResult = await createGroup.mutateAsync({
          itemId, name: g.name,
          type: g.required ? "required" : "optional",
          min_select: g.min_select,
          max_select: g.max_select,
          sort_order: gi,
          icon_key: g.icon_key,
        }) as { data: { id: string } };
        const groupId = gResult?.data?.id;
        if (groupId) {
          let ci = 0;
          for (const c of g.choices) {
            if (c.label.trim()) {
              await createChoice.mutateAsync({ groupId, label: c.label, extra_charge: c.extra_charge, sort_order: ci, input_type: c.input_type });
            }
            ci++;
          }
        }
        gi++;
      }
    }
  };

  const handleSave = async () => {
    try {
      const values = await form.validateFields();
      await doSave(values);
      void msg.success(t("addMenuItem.successCreate"));
      navigate(-1);
    } catch {
      void msg.error(t("addMenuItem.failedCreate"));
    }
  };

  const handleSaveAndAddAnother = async () => {
    try {
      const values = await form.validateFields();
      await doSave(values);
      void msg.success(t("addMenuItem.successAnother"));
      form.resetFields();
      form.setFieldsValue({ is_available: true, sort_order: 0 });
      // keep the stall selection
      setSelectedStallId(selectedStallId);
    } catch {
      void msg.error(t("addMenuItem.failedCreate"));
    }
  };

  return (
    <AdminShell>
      {/* negative margin to escape AdminShell's 24px padding */}
      <div style={{ margin: -24, display: "flex", flexDirection: "column", height: "calc(100vh - 64px)" }}>

        {/* ── Page header bar ── */}
        <div style={{
          height: 56, padding: "0 24px",
          display: "flex", alignItems: "center", gap: 16,
          background: "#fff", borderBottom: "1px solid #E5E7EB", flexShrink: 0,
        }}>
          <Button
            type="text"
            icon={<LeftOutlined />}
            onClick={() => navigate(-1)}
            style={{ padding: "0 8px", fontWeight: 600, color: "#616161" }}
          />
          <div style={{ width: 1, height: 20, background: "#E5E7EB" }} />
          <span style={{ fontSize: 20, fontWeight: 800, color: "#212121" }}>{t("addMenuItem.titlePage")}</span>
        </div>

        {/* ── Body: form + preview ── */}
        <div style={{ flex: 1, display: "flex", overflow: "hidden" }}>

          {/* Left – Form content */}
          <div style={{ flex: 1, overflowY: "auto", padding: "28px 32px", background: "#F9FAFB" }}>
            <Form
              form={form}
              layout="vertical"
              initialValues={{ is_available: true, sort_order: 0 }}
              onFinish={() => void handleSave()}
            >

              {/* ── 01  Basic Information ── */}
              <div style={{ background: "#fff", borderRadius: 16, padding: "24px 28px", marginBottom: 20, boxShadow: "0 1px 4px rgba(0,0,0,0.06)" }}>
                <SectionHead num="01" label={t("addMenuItem.sectionBasic")} />

                <Form.Item
                  name="name"
                  label={<span style={{ fontWeight: 600, fontSize: 13, color: "#212121" }}>{t("addMenuItem.itemName")}</span>}
                  rules={[{ required: true, message: t("addMenuItem.itemNameRequired") }]}
                  style={{ marginBottom: 20 }}
                >
                  <Input
                    placeholder={t("addMenuItem.namePlaceholder")}
                    maxLength={120}
                    style={{ height: 44, borderRadius: 10, fontSize: 14 }}
                  />
                </Form.Item>

                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16, marginBottom: selectedStall && !selectedStall.is_open ? 16 : 20 }}>
                  {/* Stall selector */}
                  <div>
                    <div style={{ fontSize: 13, fontWeight: 600, color: "#212121", marginBottom: 8, display: "flex", alignItems: "center", gap: 8 }}>
                      {t("addMenuItem.stall")}
                      <Tag style={{ background: "#FEE2E2", color: "#DC2626", border: "none", borderRadius: 6, fontSize: 11, fontWeight: 700, padding: "0 8px", lineHeight: "20px" }}>
                        {t("addMenuItem.tagRequired")}
                      </Tag>
                    </div>
                    <Select
                      value={selectedStallId}
                      placeholder={t("addMenuItem.selectStallPh")}
                      style={{ width: "100%", height: 44 }}
                      options={stalls.map(s => ({ value: s.id, label: s.name }))}
                      onChange={(v: string) => {
                        setSelectedStallId(v);
                        form.setFieldsValue({ category_ids: [] });
                      }}
                    />
                  </div>

                  {/* Category */}
                  <Form.Item
                    name="category_ids"
                    label={<span style={{ fontWeight: 600, fontSize: 13, color: "#212121" }}>{t("addMenuItem.category")}</span>}
                    style={{ marginBottom: 0 }}
                  >
                    <Select
                      mode="multiple"
                      allowClear
                      placeholder={t("addMenuItem.selectCategoryPh")}
                      style={{ width: "100%", minHeight: 44 }}
                      disabled={!selectedStallId}
                      options={categories.map(c => ({ value: c.id, label: `${c.emoji ? c.emoji + " " : ""}${c.name}` }))}
                    />
                  </Form.Item>
                </div>

                {/* Stall paused warning */}
                {selectedStall && !selectedStall.is_open && (
                  <div style={{
                    display: "flex", alignItems: "flex-start", gap: 10,
                    background: "#FEF2F2", borderRadius: 10, padding: "12px 16px", marginBottom: 20,
                  }}>
                    <span style={{ color: "#DC2626", fontSize: 16, flexShrink: 0, marginTop: 1 }}>⚠</span>
                    <span style={{ fontSize: 13, color: "#DC2626", lineHeight: 1.5 }}>
                      {t("addMenuItem.stallPaused", { name: selectedStall.name })}
                    </span>
                  </div>
                )}

                <Form.Item
                  name="description"
                  label={<span style={{ fontWeight: 600, fontSize: 13, color: "#212121" }}>{t("addMenuItem.description")}</span>}
                  style={{ marginBottom: 0 }}
                >
                  <Input.TextArea
                    placeholder={t("addMenuItem.descPlaceholder")}
                    rows={3}
                    maxLength={400}
                    style={{ borderRadius: 10, fontSize: 14, resize: "none" }}
                  />
                </Form.Item>
              </div>

              {/* ── 02  Pricing & Availability ── */}
              <div style={{ background: "#fff", borderRadius: 16, padding: "24px 28px", marginBottom: 20, boxShadow: "0 1px 4px rgba(0,0,0,0.06)" }}>
                <SectionHead num="02" label={t("addMenuItem.sectionPricing")} />

                <div style={{ display: "flex", alignItems: "flex-start", gap: 24 }}>
                  {/* Price */}
                  <div style={{ flex: 1 }}>
                    <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: 0.8, color: "#9E9E9E", textTransform: "uppercase", marginBottom: 8 }}>
                      {t("addMenuItem.basePrice")}
                    </div>
                    <Form.Item name="price" rules={[{ required: true, message: t("addMenuItem.priceRequired") }]} style={{ marginBottom: 0 }}>
                      <InputNumber
                        prefix={<span style={{ fontWeight: 700, color: "#9E9E9E" }}>RM</span>}
                        min={0}
                        precision={2}
                        placeholder="0.00"
                        style={{ width: "100%", height: 48, borderRadius: 10 }}
                      />
                    </Form.Item>
                  </div>

                  {/* Available for Order toggle */}
                  <div style={{
                    flex: 1,
                    display: "flex", alignItems: "center", justifyContent: "space-between",
                    background: "#F9FAFB", borderRadius: 12, padding: "16px 20px",
                    marginTop: 20,
                  }}>
                    <div>
                      <div style={{ fontWeight: 700, fontSize: 14, color: "#212121" }}>{t("addMenuItem.availableForOrder")}</div>
                      <div style={{ fontSize: 12, color: "#9E9E9E", marginTop: 2 }}>{t("addMenuItem.availableHint")}</div>
                    </div>
                    <Form.Item name="is_available" valuePropName="checked" noStyle>
                      <Switch style={{ background: isAvailable !== false ? "#16A34A" : undefined }} />
                    </Form.Item>
                  </div>
                </div>

                {/* Advanced options (collapsed) */}
                <Collapse
                  ghost
                  style={{ marginTop: 16 }}
                  items={[{
                    key: "advanced",
                    label: <span style={{ fontSize: 13, color: "#9E9E9E", fontWeight: 600 }}>{t("addMenuItem.advancedOptions")}</span>,
                    children: (
                      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 12 }}>
                        <Form.Item name="offer_price" label={<span style={{ fontSize: 12, color: "#616161" }}>{t("addMenuItem.offerPrice")}</span>} style={{ marginBottom: 0 }}>
                          <InputNumber prefix="RM" min={0} precision={2} style={{ width: "100%" }} />
                        </Form.Item>
                        <Form.Item name="daily_stock" label={<span style={{ fontSize: 12, color: "#616161" }}>{t("addMenuItem.dailyStock")}</span>} style={{ marginBottom: 0 }}>
                          <InputNumber min={1} style={{ width: "100%" }} placeholder={t("addMenuItem.dailyStockPh")} />
                        </Form.Item>
                        <Form.Item name="sort_order" label={<span style={{ fontSize: 12, color: "#616161" }}>{t("addMenuItem.sortOrder")}</span>} style={{ marginBottom: 0 }}>
                          <InputNumber min={0} style={{ width: "100%" }} />
                        </Form.Item>
                        <Form.Item name="available_from" label={<span style={{ fontSize: 12, color: "#616161" }}>{t("addMenuItem.availableFrom")}</span>} style={{ marginBottom: 0 }}>
                          <Input placeholder={t("addMenuItem.timePh")} maxLength={5} />
                        </Form.Item>
                        <Form.Item name="available_to" label={<span style={{ fontSize: 12, color: "#616161" }}>{t("addMenuItem.availableUntil")}</span>} style={{ marginBottom: 0 }}>
                          <Input placeholder={t("addMenuItem.timePhEnd")} maxLength={5} />
                        </Form.Item>
                        <Form.Item name="offer_from" label={<span style={{ fontSize: 12, color: "#616161" }}>{t("addMenuItem.offerFrom")}</span>} style={{ marginBottom: 0 }}>
                          <Input placeholder={t("addMenuItem.timePhOffer")} maxLength={5} />
                        </Form.Item>
                      </div>
                    ),
                  }]}
                />
              </div>

              {/* ── 03  Item Image ── */}
              <div style={{ background: "#fff", borderRadius: 16, padding: "24px 28px", marginBottom: 20, boxShadow: "0 1px 4px rgba(0,0,0,0.06)" }}>
                <SectionHead num="03" label={t("addMenuItem.sectionImage")} />
                <Form.Item name="image_url" style={{ marginBottom: 0 }}>
                  <ImageUpload folder="menu" />
                </Form.Item>
                {/* Upload hint when no custom uploader is shown */}
                {!previewImage && (
                  <div style={{
                    marginTop: 8,
                    border: "2px dashed #E5E7EB", borderRadius: 12,
                    padding: "40px 24px", textAlign: "center",
                    background: "#F9FAFB", cursor: "pointer",
                    display: "none", // hidden – ImageUpload component handles its own UI
                  }}>
                    <CloudUploadOutlined style={{ fontSize: 36, color: "#F97316", marginBottom: 12 }} />
                    <div style={{ fontWeight: 700, fontSize: 14, color: "#212121", marginBottom: 4 }}>
                      {t("imageUpload.clickOrDrag")}
                    </div>
                    <div style={{ fontSize: 12, color: "#9E9E9E" }}>
                      {t("imageUpload.hintFormats")}
                    </div>
                  </div>
                )}
              </div>

              {/* ── 04  Customization Engine ── */}
              <div style={{ background: "#fff", borderRadius: 16, padding: "24px 28px", marginBottom: 20, boxShadow: "0 1px 4px rgba(0,0,0,0.06)" }}>
                {/* Section header */}
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 24 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                    <span style={{
                      width: 26, height: 26, borderRadius: "50%",
                      background: "#F97316", color: "#fff",
                      fontSize: 12, fontWeight: 800,
                      display: "inline-flex", alignItems: "center", justifyContent: "center",
                    }}>04</span>
                    <span style={{ fontSize: 16, fontWeight: 800, color: "#212121" }}>{t("addMenuItem.sectionCustomization")}</span>
                  </div>
                  <div style={{
                    display: "flex", alignItems: "center", gap: 10,
                    background: "#F3F4F6", borderRadius: 20, padding: "6px 14px",
                  }}>
                    <span style={{ fontSize: 13, color: "#212121", fontWeight: 600 }}>{t("addMenuItem.enableCustomization")}</span>
                    <Switch
                      checked={custEnabled}
                      onChange={v => { setCustEnabled(v); if (!v) setGroups([]); }}
                      style={{ background: custEnabled ? "#F97316" : undefined }}
                    />
                  </div>
                </div>

                {!custEnabled ? (
                  /* Toggle OFF — prompt to enable */
                  <div style={{
                    border: "1.5px dashed #E5E7EB", borderRadius: 12,
                    padding: "36px 24px", textAlign: "center", background: "#F9FAFB",
                  }}>
                    <div style={{ fontSize: 28, marginBottom: 10 }}>⚙️</div>
                    <div style={{ fontSize: 14, fontWeight: 700, color: "#212121", marginBottom: 6 }}>
                      {t("addMenuItem.custPromptTitle")}
                    </div>
                    <div style={{ fontSize: 13, color: "#9E9E9E", lineHeight: 1.6, maxWidth: 300, margin: "0 auto" }}>
                      {t("addMenuItem.custPromptBody")}
                    </div>
                  </div>
                ) : groups.length === 0 ? (
                  /* Toggle ON, no groups yet */
                  <div>
                    <div style={{ textAlign: "center", padding: "12px 0 20px", fontSize: 13, color: "#616161" }}>
                      {t("addMenuItem.noGroupsYet")}
                    </div>
                    <button
                      type="button" onClick={addGroup}
                      style={{
                        width: "100%", height: 52,
                        border: "1.5px dashed #D1D5DB", borderRadius: 12,
                        background: "#fff", cursor: "pointer",
                        display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
                        fontSize: 14, fontWeight: 600, color: "#212121",
                      }}
                    >
                      <PlusOutlined style={{ fontSize: 16 }} /> {t("addMenuItem.addOptionGroup")}
                    </button>
                  </div>
                ) : (
                  /* Toggle ON, with groups */
                  <div>
                    {groups.map((group) => (
                      <div
                        key={group.localId}
                        style={{
                          border: "1px solid #E5E7EB", borderRadius: 12,
                          padding: "20px 20px 16px", marginBottom: 16,
                          background: "#FAFAFA",
                        }}
                      >
                        {/* ICON + GROUP NAME */}
                        <div style={{ display: "flex", gap: 12, alignItems: "flex-start", marginBottom: 16 }}>
                          {/* Preset icon picker */}
                          <div style={{ flexShrink: 0 }}>
                            <div style={{ fontSize: 10, fontWeight: 800, letterSpacing: 1, color: "#9E9E9E", textTransform: "uppercase" as const, marginBottom: 8 }}>
                              {t("addMenuItem.icon")}
                            </div>
                            <div style={{ display: "flex", gap: 6 }}>
                              {GROUP_ICON_DEFS.map(icon => {
                                const active = group.icon_key === icon.key;
                                return (
                                  <button
                                    key={icon.key}
                                    type="button"
                                    title={(() => {
                                      const lk = GROUP_ICON_LABEL_KEY[icon.key];
                                      return lk ? t(lk) : icon.key;
                                    })()}
                                    onClick={() => updateGroup(group.localId, { icon_key: active ? undefined : icon.key })}
                                    style={{
                                      width: 40, height: 40, borderRadius: 10, cursor: "pointer",
                                      border: active ? "2px solid #F97316" : "1.5px solid #E5E7EB",
                                      background: active ? "#FFF7ED" : "#F9FAFB",
                                      color: active ? "#F97316" : "#9E9E9E",
                                      display: "flex", alignItems: "center", justifyContent: "center",
                                    }}
                                  >
                                    <GroupIcon iconKey={icon.key} size={18} color={active ? "#F97316" : "#9E9E9E"} />
                                  </button>
                                );
                              })}
                            </div>
                          </div>

                          {/* Group name input */}
                          <div style={{ flex: 1 }}>
                            <div style={{ fontSize: 10, fontWeight: 800, letterSpacing: 1, color: "#9E9E9E", textTransform: "uppercase" as const, marginBottom: 8 }}>
                              {t("addMenuItem.groupName")}
                            </div>
                            <Input
                              value={group.name}
                              placeholder={t("addMenuItem.groupNamePh")}
                              onChange={e => updateGroup(group.localId, { name: e.target.value })}
                              style={{ height: 44, borderRadius: 10, fontSize: 14, background: "#F9FAFB" }}
                            />
                          </div>
                        </div>

                        {/* REQUIRED / SELECTION / MIN / MAX */}
                        <div style={{ display: "flex", alignItems: "center", gap: 20, marginBottom: 16, flexWrap: "wrap" as const }}>
                          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                            <div style={{ fontSize: 10, fontWeight: 800, letterSpacing: 1, color: "#9E9E9E", textTransform: "uppercase" as const }}>{t("addMenuItem.fieldRequired")}</div>
                            <Switch
                              size="small"
                              checked={group.required}
                              onChange={v => updateGroup(group.localId, { required: v, min_select: v ? 1 : 0 })}
                              style={{ background: group.required ? "#16A34A" : undefined }}
                            />
                          </div>
                          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                            <div style={{ fontSize: 10, fontWeight: 800, letterSpacing: 1, color: "#9E9E9E", textTransform: "uppercase" as const }}>{t("addMenuItem.selection")}</div>
                            <Select
                              value={group.selection}
                              size="small" style={{ width: 148 }}
                              options={selectionOptions}
                              onChange={(v: "single" | "multiple") => updateGroup(group.localId, {
                                selection: v,
                                max_select: v === "single" ? 1 : (group.choices.length || 1),
                              })}
                            />
                          </div>
                          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                            <div style={{ fontSize: 10, fontWeight: 800, letterSpacing: 1, color: "#9E9E9E", textTransform: "uppercase" as const }}>{t("addMenuItem.min")}</div>
                            <InputNumber
                              size="small" value={group.min_select} min={0} style={{ width: 56 }}
                              onChange={v => updateGroup(group.localId, { min_select: v ?? 0 })}
                            />
                          </div>
                          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                            <div style={{ fontSize: 10, fontWeight: 800, letterSpacing: 1, color: "#9E9E9E", textTransform: "uppercase" as const }}>{t("addMenuItem.max")}</div>
                            <InputNumber
                              size="small" value={group.max_select} min={1} style={{ width: 56 }}
                              onChange={v => updateGroup(group.localId, { max_select: v ?? 1 })}
                            />
                          </div>
                          <Button
                            type="text" danger size="small" icon={<DeleteOutlined />}
                            onClick={() => removeGroup(group.localId)}
                            style={{ marginLeft: "auto", color: "#9E9E9E", fontSize: 12 }}
                          >
                            {t("addMenuItem.removeGroup")}
                          </Button>
                        </div>

                        {/* Options table */}
                        {group.choices.length > 0 && (
                          <div style={{ marginBottom: 12 }}>
                            {/* Header */}
                            <div style={{
                              display: "grid", gridTemplateColumns: "1fr 120px 110px 60px 32px",
                              gap: 8, marginBottom: 8, padding: "0 4px",
                            }}>
                              {[t("addMenuItem.colOptionName"), t("addMenuItem.colPriceAdj"), t("addMenuItem.colType"), t("addMenuItem.colDefault"), ""].map((h, hi) => (
                                <div key={hi} style={{ fontSize: 10, fontWeight: 800, letterSpacing: 1, color: "#9E9E9E", textTransform: "uppercase" as const }}>{h}</div>
                              ))}
                            </div>
                            {/* Rows */}
                            {group.choices.map(choice => (
                              <div
                                key={choice.localId}
                                style={{
                                  display: "grid", gridTemplateColumns: "1fr 120px 110px 60px 32px",
                                  gap: 8, alignItems: "center",
                                  padding: "8px 4px", borderTop: "1px solid #F3F4F6",
                                }}
                              >
                                <Input
                                  size="small" value={choice.label} placeholder={t("addMenuItem.optionNamePh")}
                                  onChange={e => updateChoice(group.localId, choice.localId, { label: e.target.value })}
                                  style={{ borderRadius: 8 }}
                                />
                                <InputNumber
                                  size="small" value={choice.extra_charge} min={0} precision={2}
                                  formatter={v => `+${v ?? "0"}`}
                                  style={{ width: "100%", borderRadius: 8 }}
                                  onChange={v => updateChoice(group.localId, choice.localId, { extra_charge: v ?? 0 })}
                                />
                                <Select
                                  size="small"
                                  value={choice.input_type}
                                  style={{ width: "100%" }}
                                  onChange={(v: "radio" | "input" | "textarea") => updateChoice(group.localId, choice.localId, { input_type: v })}
                                  options={inputTypeOptions}
                                />
                                <div style={{ display: "flex", justifyContent: "center" }}>
                                  <Checkbox
                                    checked={choice.isDefault}
                                    onChange={e => updateChoice(group.localId, choice.localId, { isDefault: e.target.checked })}
                                  />
                                </div>
                                <Button
                                  type="text" size="small" icon={<DeleteOutlined />}
                                  onClick={() => removeChoice(group.localId, choice.localId)}
                                  style={{ color: "#9E9E9E", padding: 0 }}
                                />
                              </div>
                            ))}
                          </div>
                        )}

                        {/* + Add option */}
                        <Button
                          type="link" icon={<PlusOutlined />}
                          onClick={() => addChoice(group.localId)}
                          style={{ padding: 0, color: "#F97316", fontWeight: 600, fontSize: 13 }}
                        >
                          {t("addMenuItem.addOption")}
                        </Button>
                      </div>
                    ))}

                    {/* Add Option Group */}
                    <button
                      type="button" onClick={addGroup}
                      style={{
                        width: "100%", height: 52,
                        border: "1.5px dashed #D1D5DB", borderRadius: 12,
                        background: "#fff", cursor: "pointer",
                        display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
                        fontSize: 14, fontWeight: 600, color: "#212121",
                      }}
                    >
                      <PlusOutlined style={{ fontSize: 16 }} /> {t("addMenuItem.addOptionGroup")}
                    </button>
                  </div>
                )}
              </div>

            </Form>
          </div>

          {/* Right – Customer Preview */}
          <div style={{
            width: 280, flexShrink: 0,
            borderLeft: "1px solid #E5E7EB",
            background: "#fff", padding: "24px 20px",
            overflowY: "auto",
          }}>
            <div style={{ fontSize: 10, fontWeight: 800, letterSpacing: 1, color: "#9E9E9E", textTransform: "uppercase", marginBottom: 16 }}>
              {t("addMenuItem.customerPreview")}
            </div>

            {!selectedStallId && (
              <div style={{ textAlign: "center", color: "#9E9E9E", fontSize: 13, padding: "20px 0 16px" }}>
                {t("addMenuItem.selectStallPreview")}
              </div>
            )}

            <PreviewCard
              name={previewName}
              price={previewPrice}
              imageUrl={previewImage}
              isAvailable={isAvailable}
            />

            {!previewName && (
              <div style={{ marginTop: 16, fontSize: 12, color: "#9E9E9E", textAlign: "center", lineHeight: 1.6 }}>
                <span style={{ fontWeight: 600, color: "#212121" }}>{t("addMenuItem.previewNameFallback")}</span>
                <br />
                {t("addMenuItem.previewDescHint")}
              </div>
            )}
          </div>
        </div>

        {/* ── Footer bar ── */}
        <div style={{
          height: 64, padding: "0 24px",
          display: "flex", alignItems: "center", justifyContent: "space-between",
          background: "#fff", borderTop: "1px solid #E5E7EB", flexShrink: 0,
        }}>
          {/* Mandatory fields indicator */}
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <CheckCircleFilled style={{ fontSize: 18, color: mandatoryComplete ? "#16A34A" : "#D1D5DB" }} />
            <span style={{ fontSize: 13, color: mandatoryComplete ? "#166534" : "#9E9E9E", fontWeight: 600 }}>
              {mandatoryComplete ? t("addMenuItem.mandatoryComplete") : t("addMenuItem.mandatoryIncomplete")}
            </span>
          </div>

          <div style={{ display: "flex", gap: 12 }}>
            <Button
              style={{ height: 44, borderRadius: 8, fontWeight: 600, minWidth: 160 }}
              onClick={() => void handleSaveAndAddAnother()}
              loading={createItem.isPending}
              disabled={!mandatoryComplete}
            >
              {t("addMenuItem.saveAddAnother")}
            </Button>
            <Button
              type="primary"
              style={{ height: 44, borderRadius: 8, fontWeight: 700, background: "#F97316", border: "none", minWidth: 120 }}
              onClick={() => void handleSave()}
              loading={createItem.isPending}
              disabled={!selectedStallId}
            >
              {t("addMenuItem.saveItem")}
            </Button>
          </div>
        </div>

      </div>
    </AdminShell>
  );
}
