import { useParams, useNavigate } from "react-router-dom";
import { Button, Skeleton, Typography } from "antd";
import {
  ArrowLeftOutlined, UserOutlined, TransactionOutlined,
  FileTextOutlined, DollarOutlined, CheckCircleFilled,
  ClockCircleFilled, InfoCircleFilled,
} from "@ant-design/icons";
import { useTranslation } from "react-i18next";
import { formatDateTimeDetail } from "../utils/formatLocaleDate";
import type { TFunction } from "i18next";
import { AdminShell } from "../layouts/AdminShell";
import { tokens } from "../styles/tokens";
const { color: T } = tokens;
import { useAdminRefund } from "../api/hooks";

const { Text } = Typography;

// ─── Constants (visual only) ───────────────────────────────────────────────────

const STATUS_STYLE: Record<string, { bg: string; color: string }> = {
  success:  { bg: T.successBgAlt, color: "#065F46" },
  pending:  { bg: T.warningBg, color: T.brandAmberText },
  rejected: { bg: T.dangerBg, color: T.dangerDeep },
  failed:   { bg: T.surfaceSection, color: T.textSecondary },
};

const DEFAULT_STATUS_STYLE = { bg: T.warningBg, color: T.brandAmberText };

// ─── Helpers ─────────────────────────────────────────────────────────────────

function Card({ children, style }: { children: React.ReactNode; style?: React.CSSProperties }) {
  return (
    <div style={{
      background: T.surface, borderRadius: 12, border: "1px solid #E5E7EB",
      padding: "20px 24px", ...style,
    }}>
      {children}
    </div>
  );
}

function SectionLabel({ children, icon }: { children: React.ReactNode; icon?: React.ReactNode }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 16 }}>
      {icon && <span style={{ color: T.textMuted, fontSize: 14 }}>{icon}</span>}
      <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.8, color: T.textMuted, textTransform: "uppercase" }}>
        {children}
      </span>
    </div>
  );
}

function InfoRow({ label, value }: { label: string; value: React.ReactNode }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 12, gap: 12 }}>
      <span style={{ fontSize: 13, color: T.textBody, flexShrink: 0 }}>{label}</span>
      <span style={{ fontSize: 13, fontWeight: 600, color: T.textDark, textAlign: "right" }}>{value}</span>
    </div>
  );
}

// ─── Timeline ────────────────────────────────────────────────────────────────

type TimelineEvent = {
  label: string;
  time: string;
  staff: string;
  dotColor: string;
};

function buildTimeline(
  t: TFunction,
  lng: string,
  logs: Array<{ id: string; action: string; created_at: string; meta: Record<string, unknown> | null; staff: { name: string } | null }>,
  refundStatus: string,
  createdAt: string,
): TimelineEvent[] {
  const events: TimelineEvent[] = [];
  const dash = t("refundDetail.dash");

  const createLog = logs.find((l) => l.action === "refund.created" || l.action === "create");
  events.push({
    label: t("refundDetail.timelineCreated"),
    time: formatDateTimeDetail(createLog?.created_at ?? createdAt, lng),
    staff: createLog?.staff?.name ?? t("refundDetail.staffSystem"),
    dotColor: T.textMuted,
  });

  const processLog = logs.find((l) =>
    l.action === "refund.reviewed" || l.action === "review" ||
    l.action === "refund.processing" || l.action === "update"
  );
  if (processLog) {
    events.push({
      label: t("refundDetail.timelineProcessing"),
      time: formatDateTimeDetail(processLog.created_at, lng),
      staff: processLog.staff?.name ?? t("refundDetail.staffAdmin"),
      dotColor: T.brand,
    });
  }

  if (refundStatus === "success") {
    const completeLog = logs.find((l) => l.action === "refund.completed" || l.action === "approve");
    events.push({
      label: t("refundDetail.timelineCompleted"),
      time: completeLog ? formatDateTimeDetail(completeLog.created_at, lng) : dash,
      staff: completeLog?.staff?.name ?? t("refundDetail.staffAdmin"),
      dotColor: T.successBright,
    });
  } else if (refundStatus === "rejected") {
    const rejectLog = logs.find((l) => l.action === "refund.rejected" || l.action === "reject");
    events.push({
      label: t("refundDetail.timelineRejected"),
      time: rejectLog ? formatDateTimeDetail(rejectLog.created_at, lng) : dash,
      staff: rejectLog?.staff?.name ?? t("refundDetail.staffAdmin"),
      dotColor: T.dangerText,
    });
  }

  return events.reverse();
}

// ─── Main screen ─────────────────────────────────────────────────────────────

export function RefundDetailScreen() {
  const { t, i18n } = useTranslation();
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { data: refund, isLoading } = useAdminRefund(id);

  if (isLoading) {
    return (
      <AdminShell>
        <div style={{ padding: "28px 32px" }}>
          <Skeleton active paragraph={{ rows: 10 }} />
        </div>
      </AdminShell>
    );
  }

  if (!refund) {
    return (
      <AdminShell>
        <div style={{ padding: "28px 32px" }}>
          <Button
            type="text"
            icon={<ArrowLeftOutlined />}
            onClick={() => navigate("/refunds")}
            style={{ fontWeight: 700, color: T.textBody, marginBottom: 16 }}
          >
            {t("refundDetail.back")}
          </Button>
          <div style={{ color: T.dangerText }}>{t("refundDetail.notFound")}</div>
        </div>
      </AdminShell>
    );
  }

  const statusStyle = STATUS_STYLE[refund.status] ?? DEFAULT_STATUS_STYLE;
  const statusLabel = t(`refundDetail.status.${refund.status}`, { defaultValue: refund.status.toUpperCase() });
  const typeLabel = refund.type === "full"
    ? t("refundDetail.typeFull")
    : refund.type === "partial"
      ? t("refundDetail.typePartial")
      : refund.type;
  const customer = refund.order?.customer ?? refund.customer;
  const meta = refund.activity_logs?.[0]?.meta as Record<string, unknown> | null ?? null;
  const customerExtra = (customer ?? {}) as Record<string, unknown>;
  const customerPhone = typeof customerExtra.phone === "string" ? customerExtra.phone : null;
  const customerEmail = typeof customerExtra.email === "string" ? customerExtra.email : null;

  let transferMethod = "";
  let transferTime = "";
  let merchantNote = "";

  for (const log of refund.activity_logs ?? []) {
    if (log.meta?.transfer_method) {
      transferMethod = String(log.meta.transfer_method);
      transferTime = String(log.meta.transfer_time ?? "");
      merchantNote = String(log.meta.note ?? "");
      break;
    }
  }
  if (!merchantNote && refund.rejection_note) merchantNote = refund.rejection_note;

  const rfdId = `RF-${refund.id.slice(-4).toUpperCase()}`;
  const txnRef = refund.transaction?.reference?.toUpperCase()
    ?? `TXN-${refund.transaction?.id?.slice(0, 16).toUpperCase() ?? t("refundDetail.dash")}`;
  const orderCode = refund.order?.order_code ?? t("refundDetail.dash");

  const timeline = buildTimeline(t, i18n.language, refund.activity_logs ?? [], refund.status, refund.created_at);

  void meta;

  return (
    <AdminShell>
      <div style={{ padding: "28px 32px", background: T.bg, minHeight: "100vh" }}>

        <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 28 }}>
          <Button
            type="text"
            icon={<ArrowLeftOutlined />}
            onClick={() => navigate("/refunds")}
            style={{ fontWeight: 700, color: T.textBody }}
          >
            {t("refundDetail.back")}
          </Button>
          <div style={{ fontSize: 24, fontWeight: 800, color: T.textDark }}>{t("refundDetail.title")}</div>
          <span style={{
            background: statusStyle.bg, color: statusStyle.color,
            borderRadius: 20, padding: "4px 14px", fontSize: 12, fontWeight: 800, letterSpacing: 0.5,
          }}>
            {statusLabel}
          </span>
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16, marginBottom: 16 }}>

          <Card>
            <div style={{ marginBottom: 20 }}>
              <div style={{ fontSize: 12, color: T.textMuted, fontWeight: 700, letterSpacing: 0.5, textTransform: "uppercase", marginBottom: 6 }}>
                {t("refundDetail.refundIdLabel")}
              </div>
              <div style={{ fontSize: 32, fontWeight: 900, color: T.textDark }}>{rfdId}</div>
            </div>
            <div style={{ marginBottom: 20 }}>
              <div style={{ fontSize: 12, color: T.textMuted, fontWeight: 700, textTransform: "uppercase", marginBottom: 6 }}>
                {t("refundDetail.amountReclaimedLabel")}
              </div>
              <div style={{ fontSize: 28, fontWeight: 900, color: T.brand }}>
                RM {Number(refund.amount).toFixed(2)}
              </div>
            </div>
            <InfoRow label={t("refundDetail.refundType")} value={typeLabel} />
            <InfoRow label={t("refundDetail.createdTime")} value={formatDateTimeDetail(refund.created_at, i18n.language)} />
            <InfoRow label={t("refundDetail.requestSource")} value={t("refundDetail.requestSourcePos")} />
          </Card>

          <Card>
            <SectionLabel icon={<UserOutlined />}>{t("refundDetail.customerInfo")}</SectionLabel>
            {customer ? (
              <>
                <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 16 }}>
                  <div style={{
                    width: 44, height: 44, borderRadius: "50%",
                    background: T.brandLight, display: "flex", alignItems: "center", justifyContent: "center",
                    fontSize: 18, color: T.brand, fontWeight: 800,
                  }}>
                    {(customer.name ?? t("refundDetail.guest")).charAt(0).toUpperCase()}
                  </div>
                  <div>
                    <div style={{ fontSize: 15, fontWeight: 700, color: T.textDark }}>
                      {customer.name ?? t("refundDetail.guest")}
                    </div>
                    <div style={{ fontSize: 11, color: T.textMuted }}>{t("orderDetail.customerShortId", { id: customer.id.slice(-4) })}</div>
                  </div>
                </div>
                {customerPhone && <InfoRow label={t("refundDetail.phone")} value={customerPhone} />}
                {customerEmail && <InfoRow label={t("refundDetail.email")} value={customerEmail} />}
              </>
            ) : (
              <Text style={{ color: T.textMuted }}>{t("refundDetail.noCustomer")}</Text>
            )}
          </Card>
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16, marginBottom: 16 }}>

          <Card>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 16 }}>
              <SectionLabel icon={<TransactionOutlined />}>{t("refundDetail.transactionInfo")}</SectionLabel>
              <Button
                type="link"
                size="small"
                style={{ color: T.brand, fontWeight: 700, padding: 0 }}
                onClick={() => navigate(`/transactions/${refund.transaction?.id}`)}
              >
                {t("refundDetail.viewTransaction")}
              </Button>
            </div>
            <InfoRow label={t("refundDetail.transactionId")} value={
              <span style={{ fontFamily: "monospace", color: T.brand }}>{txnRef}</span>
            } />
            <InfoRow label={t("refundDetail.orderId")} value={
              <span
                style={{ color: T.brand, fontWeight: 700, cursor: "pointer" }}
                onClick={() => navigate(`/orders/${refund.order?.id ?? ""}`)}
              >
                #{orderCode}
              </span>
            } />
            <InfoRow label={t("refundDetail.paymentMethod")} value={refund.transaction?.method ?? t("refundDetail.dash")} />
            <InfoRow label={t("refundDetail.totalPaid")} value={`RM ${Number(refund.transaction?.amount ?? 0).toFixed(2)}`} />
          </Card>

          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>

            <Card style={{ padding: "16px 20px" }}>
              <SectionLabel icon={<FileTextOutlined />}>{t("refundDetail.refundReason")}</SectionLabel>
              <Text style={{ fontSize: 14, color: T.textDark }}>{refund.reason}</Text>
            </Card>

            {merchantNote && !transferMethod && (
              <Card style={{ padding: "16px 20px" }}>
                <SectionLabel icon={<InfoCircleFilled />}>{t("refundDetail.internalNote")}</SectionLabel>
                <Text style={{ fontSize: 14, color: T.textDark }}>{merchantNote}</Text>
              </Card>
            )}

            {transferMethod && (
              <div style={{
                background: T.surfaceGreen, border: "1px solid #BBF7D0",
                borderRadius: 12, padding: "16px 20px",
              }}>
                <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 16 }}>
                  <DollarOutlined style={{ color: T.successBright, fontSize: 16 }} />
                  <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.8, color: T.successBright, textTransform: "uppercase" }}>
                    {t("refundDetail.transferDetails")}
                  </span>
                </div>
                <InfoRow label={t("refundDetail.method")} value={transferMethod} />
                {transferTime && <InfoRow label={t("refundDetail.time")} value={transferTime} />}
                {merchantNote && (
                  <div style={{ marginTop: 8 }}>
                    <div style={{ fontSize: 11, color: T.successBright, fontWeight: 700, marginBottom: 4 }}>{t("refundDetail.merchantNoteUpper")}</div>
                    <Text italic style={{ fontSize: 13, color: T.successText }}>{merchantNote}</Text>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>

        <Card>
          <SectionLabel icon={<ClockCircleFilled />}>{t("refundDetail.processTimeline")}</SectionLabel>
          <div style={{ paddingLeft: 8 }}>
            {timeline.map((event, i) => (
              <div key={i} style={{ display: "flex", gap: 16, position: "relative", paddingBottom: i < timeline.length - 1 ? 24 : 0 }}>
                {i < timeline.length - 1 && (
                  <div style={{
                    position: "absolute", left: 9, top: 20, bottom: 0,
                    width: 2, background: T.border,
                  }} />
                )}
                <div style={{
                  width: 20, height: 20, borderRadius: "50%",
                  background: event.dotColor, flexShrink: 0, marginTop: 2,
                  display: "flex", alignItems: "center", justifyContent: "center",
                }}>
                  <div style={{ width: 8, height: 8, borderRadius: "50%", background: T.surface }} />
                </div>
                <div>
                  <div style={{ fontSize: 14, fontWeight: 700, color: T.textDark }}>{event.label}</div>
                  <div style={{ fontSize: 12, color: T.textMuted, marginTop: 2 }}>
                    {event.time} &nbsp;/&nbsp; {event.staff}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </Card>

      </div>
    </AdminShell>
  );
}
